window.BENAK_QUOTES = [{"slug": "kalendar", "title_hr": "Kalendar", "title_en": "The Calendar", "hr": ["I godina nova dođe,", "djedu, baki pišeš pismo.", "Sve nam tako lijepo prođe –", "za godinu stariji smo!"], "en": ["Then the New Year comes around,", "you write \"Grandpa, Granny dear…\";", "all goes by so safe and sound —", "we are older by a year!"], "day": "01-01", "occ_hr": "Nova godina", "occ_en": "New Year's Day"}, {"slug": "vrati-mi-poljupce", "title_hr": "Vrati mi poljupce", "title_en": "Give Me Back My Kisses", "hr": ["Za tople poglede", "ljubit sam te znao.", "Za svaki tvoj poljubac,", "po dva sam ti dao."], "en": ["For your warm glances", "I would kiss you, it's true.", "For every kiss of yours", "I gave you two."], "day": "01-02", "occ_hr": "napisano na današnji dan, 1985.", "occ_en": "written on this day in 1985"}, {"slug": "postovana-gospodo-ana", "title_hr": "Poštovana gospođo Ana!", "title_en": "Dear Madam Ana!", "hr": ["Pratili Vas samo sretni dani,", "nek' Vam bude bolje nego lani.", "Među sobom divno se družili,", "svoje snove sretno ostvarili."], "en": ["May only happy days be yours to know,", "and fare much better than a year ago.", "May you have lovely times in company,", "and see your dreams fulfilled most happily."], "day": "01-03"}, {"slug": "zima", "title_hr": "Zima", "title_en": "Winter", "hr": ["Sva se djeca", "zdrava, čila,", "kraj ognjišta sakupila", "i miluju macu slatku,", "koja prede sve po taktu."], "en": ["All the children,", "hale and bright,", "round the hearth have gathered tight,", "and are stroking kitty sweet,", "who purrs on and keeps the beat."], "day": "01-04"}, {"slug": "draga-generacijo", "title_hr": "Draga generacijo!", "title_en": "My Dear Generation!", "hr": ["Svi u zdravlju sreću uživali", "Godinicu u ljepoti snili", "Vedri dani veseli bez rada", "Ne tražite Svetog Petra vrata."], "en": ["May you in health have happiness, my friends,", "and dream in beauty till the whole year ends;", "bright merry days, with work to do no more —", "and don't go looking for Saint Peter's door."], "day": "01-05"}, {"slug": "sveta-tri-kralja", "title_hr": "Sveta tri kralja", "title_en": "The Three Kings", "hr": ["Čuo jesam da se kralj rodio.", "Iz daljine ja sam dohodio.", "Došao sam da mu se poklonim", "i bogate darove donosim."], "en": ["I heard it told a newborn king had come;", "from far away I've journeyed, far from home.", "I've come to pay him homage and to bow,", "and bring rich gifts, which I shall give him now."], "day": "01-06", "occ_hr": "Sveta tri kralja", "occ_en": "Epiphany"}, {"slug": "da-se-ne-zaboravi", "title_hr": "Da se ne zaboravi", "title_en": "Lest It Be Forgotten", "hr": ["Još se sjećam svojega djetinjstva", "i mladosti što je Sopjem prošla.", "Svu ljepotu srcem dajem Sopju,", "u vremenu kad je starost došla."], "en": ["I still remember all my childhood years", "and youth that passed in Sopje, day by day.", "To Sopje, with my heart, I give all beauty,", "now in the time when old age comes my way."], "day": "01-07", "occ_hr": "napisano na današnji dan, 2013.", "occ_en": "written on this day in 2013"}, {"slug": "nedjelja-je-i-veselje-traje", "title_hr": "Nedjelja je i veselje traje", "title_en": "It's Sunday, and the Merriment Goes On", "hr": ["Šokadijo mili zavičaju,", "najljepša si u zemaljskom raju.", "Svako selo ima tamburaša,", "lijepih cura i čarobnih snaša!"], "en": ["Šokadija, dear homeland of mine,", "in earthly paradise the fairest one!", "Each village has its tambura players fine,", "fair girls and charming young wives, every one!"], "day": "01-08", "occ_hr": "napisano na današnji dan, 2013.", "occ_en": "written on this day in 2013"}, {"slug": "zimska-idila", "title_hr": "Zimska idila", "title_en": "Winter Idyll", "hr": ["Sniježak prši, a vatra pucketa,", "topla soba kao usred ljeta.", "Kamin grije, žena kavu sprema,", "mačor prede, kraj kamina drijema.", "I zima će kraće da vam traje,", "tu idilu samo kamin daje."], "en": ["The snowflakes whirl, the fire crackles bright,", "the room's as warm as summer at its height.", "The fireplace warms, the wife makes coffee, and", "the tomcat purrs and dozes close at hand.", "And winter will seem shorter as it goes;", "that idyll only a fireplace bestows."], "day": "01-09"}, {"slug": "najveca-neznalica", "title_hr": "Najveća neznalica", "title_en": "The Greatest Know-Nothing", "hr": ["Tko najmanje na tom svijetu znade,", "to je šofer kada zbraja jade.", "Dok umoran u kabini drijema,", "šofer ne zna što se njemu sprema."], "en": ["Who in this world knows least of anyone?", "The driver, counting troubles one by one.", "While dozing in his cab, tired to the core,", "the driver doesn't know what lies in store."], "day": "01-10", "occ_hr": "napisano na današnji dan, 1988.", "occ_en": "written on this day in 1988"}, {"slug": "u-mom-narucju", "title_hr": "U mom naručju", "title_en": "In My Arms", "hr": ["U naručju kad si mome,", "ja ni za šta ne znam više.", "Da l' mećava snježna vije,", "il' jesenje liju kiše."], "en": ["When you're in my arms, my dear,", "nothing else I know at all,", "whether snowy blizzards blow", "or the autumn rains may fall."], "day": "01-11"}, {"slug": "kalendar", "title_hr": "Kalendar", "title_en": "The Calendar", "hr": ["U siječnju se drva sijeku", "i djed djeci priča bajke,", "u veljači snijeg još vije,", "ulicama jure sanjke."], "en": ["In January wood is chopped,", "Grandpa's tales the children hear;", "February, snow still swirls,", "sledges down the streets career."], "day": "01-12"}, {"slug": "dodi-voljena", "title_hr": "Dođi voljena", "title_en": "Come, My Beloved", "hr": ["I tugu je lakše", "nositi udvoje,", "kad ju se s nekim", "iskreno dijeli."], "en": ["Sorrow, too, is lighter", "when carried by two,", "when shared with another", "sincerely and true."], "day": "01-13"}, {"slug": "slavonac-u-brdima", "title_hr": "Slavonac u brdima!", "title_en": "A Slavonian in the Hills!", "hr": ["Svud je lijepo za trenutak.", "Da me pusta želja mine,", "ja poželih topli kutak,", "bijela kruha i slanine."], "en": ["Every place is fine a while.", "So this longing would be through,", "all I wished was a warm corner,", "some white bread, and bacon too."], "day": "01-14"}, {"slug": "rodena-gruda", "title_hr": "Rođena gruda", "title_en": "Native Soil", "hr": ["Ako ti se prohtje, u bijeli svijet pođi.", "Život bolne drame priređuje često.", "A kada se vratiš, na grudi mi dođi.", "Tu ćeš naći uvijek svoje toplo gnijezdo."], "en": ["If you should wish it, go into the wide world — go!", "For life will often stage its dramas full of pain.", "But when you come back home, come to my breast; you know", "that here you'll always find your own warm nest again."], "day": "01-15", "occ_hr": "napisano na današnji dan, 1976.", "occ_en": "written on this day in 1976"}, {"slug": "spoj-na-kraju-ulice", "title_hr": "Spoj na kraju ulice", "title_en": "A Date at the End of the Street", "hr": ["Čekam, a studen me bije.", "Magla se spušta plava.", "Na nebu zvijezde se pale", "i grad polako već spava."], "en": ["I wait, and the cold bites hard,", "the blue mist is coming down;", "the stars in the sky are kindling,", "and slowly sleeps the town."], "day": "01-16"}, {"slug": "protiv-svoje-volje", "title_hr": "Protiv svoje volje", "title_en": "Against My Will", "hr": ["Prši sniježak u noćima hladnim,", "žena grije od furune bolje.", "Ljubljah strasno u noćima dugim,", "došla djeca, i bez moje volje."], "en": ["On chilly nights the snow would flurry down;", "a wife warms better than the stove. I'd fill", "the long nights up with ardent love, and then", "the children came, and that without my will."], "day": "01-17"}, {"slug": "ja-mrzim", "title_hr": "Ja mrzim!", "title_en": "I Hate!", "hr": ["Ja mrzim dvorce", "i ne volim kule,", "tvrđave i vile", "i sva zdanja", "bez ljudske topline."], "en": ["I hate castles", "and do not love towers,", "fortresses and villas", "and all the buildings", "without human warmth."], "day": "01-18", "occ_hr": "napisano na današnji dan, 1975.", "occ_en": "written on this day in 1975"}, {"slug": "pitalice", "title_hr": "Pitalice", "title_en": "Questions", "hr": ["Ljeto zimi ode", "u krajeve druge,", "ugrijati djecu", "nakon zime duge."], "en": ["Summer, in the winter,", "goes to lands elsewhere,", "to warm the children after", "the long winter there."], "day": "01-19"}, {"slug": "sijeno-za-krave", "title_hr": "Sijeno za krave", "title_en": "Hay for Cows", "hr": ["Tako od postanka znaju krave,", "da ne jedu meso, već samo trave."], "en": ["Since time began, the cows have always known", "they don't eat meat, but grass, and grass alone."], "day": "01-20", "occ_hr": "napisano na današnji dan, 2001.", "occ_en": "written on this day in 2001"}, {"slug": "jucer-digla-baka", "title_hr": "Jučer digla baka", "title_en": "Yesterday Grandma Held Her Head High", "hr": ["Unuče je baki", "dio njene sreće,", "unuče je baki", "bogatstvo najveće."], "en": ["A grandchild is to Grandma", "a part of all her bliss;", "a grandchild is to Grandma", "the greatest wealth there is."], "day": "01-21"}, {"slug": "stiglo-nam-i-vincekovo", "title_hr": "Stiglo nam i Vincekovo", "title_en": "Now St Vincent's Day Has Come", "hr": ["Stiglo nam je već i Vincekovo,", "čokoti se dobrim vinom krste", "i domaćom delicijom kite,", "da bi loze bile, rodne, čvrste."], "en": ["Now St Vincent's Day has come already:", "vine-stocks christened with good wine, and hung", "all about with homemade delicacies,", "so the vines grow fruitful, firm and strong."], "day": "01-22", "occ_hr": "Vincekovo · napisano na današnji dan, 2015.", "occ_en": "St Vincent's Day · written on this day in 2015"}, {"slug": "prijatelju-jozi-santaku", "title_hr": "Prijatelju Jozi Šantaku", "title_en": "To My Friend Jozo Šantak", "hr": ["U ravnini Podravine", "rodila me moja mati,", "mnogo znanja u djetinjstvu,", "nije mogla meni dati."], "en": ["In the Podravina lowland", "it was there my mother bore me;", "much of learning, in my childhood,", "she could never lay before me."], "day": "01-23", "occ_hr": "napisano na današnji dan, 2013.", "occ_en": "written on this day in 2013"}, {"slug": "gripa", "title_hr": "Gripa", "title_en": "The Flu", "hr": ["Mali je šaran", "gripu dobio.", "Nos mu curi", "i boli ga glava."], "en": ["The little carp", "has caught the flu.", "His nose is running,", "he's got an aching head."], "day": "01-24"}, {"slug": "procvjetala-stara-lipa", "title_hr": "Procvjetala stara lipa", "title_en": "The Old Linden Is in Bloom", "hr": ["Godinama još će cvasti,", "mirisni nam dati čaj.", "Kad snijeg vije,", "čaj se pije,", "svima nam je tada raj."], "en": ["Many years yet it will flower,", "give us fragrant tea to share.", "When snow's blowing,", "tea is flowing —", "heaven for us all, right there."], "day": "01-25"}, {"slug": "zimska-idila", "title_hr": "Zimska idila", "title_en": "Winter Idyll", "hr": ["Mraz je pao i studen me hvata,", "došla zima i na moja vrata.", "Sav se ježim kad vjetar zacvili,", "a da li ste ogrjev nabavili?"], "en": ["The frost has come, the cold has gripped me fast,", "and winter's reached my door as well at last.", "I'm all goosebumps when the wind starts to whine —", "and have you got your firewood in, in time?"], "day": "01-26"}, {"slug": "ne-placi", "title_hr": "Ne plači!", "title_en": "Don't Cry!", "hr": ["Nasmiješi se malo kad si pokraj mene.", "Da nam slatka ljubav kao rijeka teče.", "Zaboravi tugu i te bolne sjene.", "Neka bude više u životu sreće."], "en": ["Smile a little bit whenever you're with me,", "so that our sweet love may flow just like a river.", "Forget the grief, those painful shadows, let them be.", "Let our life hold more of happiness than ever."], "day": "01-27", "occ_hr": "napisano na današnji dan, 1974.", "occ_en": "written on this day in 1974"}, {"slug": "prva-zekina-zima", "title_hr": "Prva Zekina zima", "title_en": "Little Bunny's First Winter", "hr": ["Nešto čudno se događa,", "vjetar vije, sniježak prši,", "mali zeko šape gladi,", "a studen mu štipa uši."], "en": ["Something strange is happening here:", "wind is blowing, snowflakes swirl,", "little bunny rubs his paws,", "and the frost nips at each ear."], "day": "01-28"}, {"slug": "kolinje-u-drenovcima", "title_hr": "Kolinje u Drenovcima", "title_en": "Kolinje in Drenovci", "hr": ["Svud se čuje kako cvile gice,", "melju meso, prave kobasice", "i kulene, šunke i slanine,", "da se zimi topiš od miline."], "en": ["You hear the piggies squealing everywhere;", "they grind the meat, make sausages with care,", "and kulens, hams and bacon, so that you", "will melt with pleasure all the winter through."], "day": "01-29"}, {"slug": "ne-budi-me-majko-rano", "title_hr": "Ne budi me, majko, rano", "title_en": "Don't Wake Me Early, Mother", "hr": ["Ne budi me, majko, rano.", "Još se nisam naspavao.", "Kad mi draga u san dođe,", "za te snove sve bih dao."], "en": ["Mother, do not wake me early,", "I am not yet rested, no.", "When my love comes in my dreaming,", "all I'd give to keep it so."], "day": "01-30"}, {"slug": "obitelji-nikolic", "title_hr": "Obitelji Nikolić!", "title_en": "To the Nikolić Family!", "hr": ["Bakino sunašce", "kad se probudi:", "pa zar ima nešto", "ljepše, dragi ljudi."], "en": ["Grandma's little sunshine,", "when he wakes from sleep:", "is there anything lovelier,", "dear people, you could seek?"], "day": "01-31", "occ_hr": "napisano na današnji dan, 2014.", "occ_en": "written on this day in 2014"}, {"slug": "most-po-kome-gazis", "title_hr": "Most po kome gaziš", "title_en": "The Bridge You Walk Across", "hr": ["Sada nosim života breme.", "Most sam po kome gaziš.", "A kada prođe naše vrijeme,", "kasno će biti da me maziš."], "en": ["Now I carry life's great weight;", "I'm the bridge on which you tread.", "When our time has passed, too late", "it will be to stroke my head."], "day": "02-01"}, {"slug": "ljubav-i-bol", "title_hr": "Ljubav i bol", "title_en": "Love and Pain", "hr": ["Ljubav je davanje.", "Ljubav je primanje.", "I što više daješ,", "to duže traje."], "en": ["Love is giving.", "Love is receiving.", "And the more you give,", "the longer it will stay."], "day": "02-02"}, {"slug": "pitalice", "title_hr": "Pitalice", "title_en": "Questions", "hr": ["Reci, gdje se zima", "po ljetu smrzava", "i pokaži krevet", "u kojem snijeg spava."], "en": ["Tell me, in the summer", "where does winter freeze?", "And show me the bed", "where the snow sleeps, please."], "day": "02-03"}, {"slug": "kada-ti-dosada-dusu-truje", "title_hr": "Kada Ti dosada dušu truje", "title_en": "When Boredom Poisons Your Soul", "hr": ["Kada Ti dosada dušu truje,", "kada te mora iz snova budi,", "kada Te očaj u životu snađe,", "kada već misliš da tonu lađe,", "pročitaj pjesme iz knjige ove,", "pa će Ti radost ozariti snove."], "en": ["When boredom is poisoning your soul,", "when nightmares wake you out of your sleep,", "when in your life despair has taken hold,", "when you think your ships are sinking deep,", "then read these poems from this book of mine,", "and joy will make your dreams begin to shine."], "day": "02-04"}, {"slug": "za-drustvo-prijatelja-starina", "title_hr": "Za Društvo prijatelja starina", "title_en": "For the Society of Friends of Antiquities", "hr": ["Za nas mladost više ne postoji,", "jer smo časno mi DRUŠTVO STARINA,", "trebali bi više se družiti,", "to bi bila baš prava milina."], "en": ["For us there's no more youth, that's been and gone,", "for we're the honoured Society of Antiques;", "we ought to get together more, for that", "would be a real delight, the best of treats."], "day": "02-05", "occ_hr": "napisano na današnji dan, 2014.", "occ_en": "written on this day in 2014"}, {"slug": "zima", "title_hr": "Zima", "title_en": "Winter", "hr": ["Došla zima.", "Snijeg je pao,", "pa krovove zatrpao.", "Iz dimnjaka dim se vije,", "kraj pećice hladno nije."], "en": ["Winter came.", "Down fell snow,", "burying the roofs below.", "From the chimney smoke curls high;", "by the stove no cold comes nigh."], "day": "02-06"}, {"slug": "domovino-moja", "title_hr": "Domovino moja", "title_en": "My Homeland", "hr": ["I kad umrem ti ćeš dalje cvasti", "i majčinski širit krila svoja.", "Dok je tebe, Šokadijo, mila,", "bit će dičnih ljudi i heroja!"], "en": ["And when I die, you'll blossom on and on,", "and spread your wings, as mothers always do;", "as long as you are here, dear Šokadija,", "there will be worthy people, heroes too!"], "day": "02-07", "occ_hr": "napisano na današnji dan, 1997.", "occ_en": "written on this day in 1997"}, {"slug": "djetlic", "title_hr": "Djetlić", "title_en": "The Woodpecker", "hr": ["Jutros kad je kljucao", "neki tvrdi dub,", "maloga je djetlića", "zabolio zub."], "en": ["This morning, as he pecked", "at a hard oak tree,", "the little woodpecker's", "tooth ached terribly."], "day": "02-08"}, {"slug": "djeca-snjeska-napravila", "title_hr": "Djeca snješka napravila", "title_en": "The Children Made a Snowman", "hr": ["Došla zima, sniježak pršti", "i dječici štipa uši.", "Bijeli sniježak tiho pada,", "to idila zimska vlada."], "en": ["Winter's come, and snow is sprinkling,", "children's ears it's nipping, tingling.", "White the snow falls, soft and slow:", "winter's idyll reigns below."], "day": "02-09", "occ_hr": "napisano na današnji dan, 2014.", "occ_en": "written on this day in 2014"}, {"slug": "moje-ce-te-oci-oplakati", "title_hr": "Moje će te oči oplakati!", "title_en": "My Eyes Will Weep for You!", "hr": ["Za svu sreću i tvoje poljupce.", "Za svu ljubav, koju si mi dala,", "za sve suze, moje radosnice,", "riječ je mala da ti kažem hvala."], "en": ["For all the joy we had, and all your kisses,", "for all the love that you have given me,", "for all the tears, my tears of happiness,", "\"thank you\" is much too small a word from me."], "day": "02-10", "occ_hr": "napisano na današnji dan, 1975.", "occ_en": "written on this day in 1975"}, {"slug": "ne-reci-da-me-volis", "title_hr": "Ne reci da me voliš", "title_en": "Don't Say You Love Me", "hr": ["Ne reci da me voliš,", "to govore oči tvoje,", "dok srce tvoje meni,", "ljubavnu pjesmu poje."], "en": ["Do not say you love me,", "for your eyes say it, dear,", "while your heart is singing", "love songs in my ear."], "day": "02-11", "occ_hr": "napisano na današnji dan, 1990.", "occ_en": "written on this day in 1990"}, {"slug": "prijatelju-glazbeniku", "title_hr": "Prijatelju, glazbeniku!", "title_en": "To My Friend, the Musician!", "hr": ["Od pjesnika umjetniku,", "nek nam bude to na diku,", "što stvaramo našim radom,", "ovom svijetu ljepšu sliku."], "en": ["From a poet to an artist:", "let it be our pride and grace", "that we give, through all our labours,", "to this world a lovelier face."], "day": "02-12", "occ_hr": "napisano na današnji dan, 2014.", "occ_en": "written on this day in 2014"}, {"slug": "ima-li-sto-slade-od-meda", "title_hr": "Ima li što slađe od meda", "title_en": "Is There Anything Sweeter Than Honey", "hr": ["Ima li što slađe od meda,", "kojega pčele roje?", "Slađe mogu biti,", "jedino usne tvoje."], "en": ["Is there anything sweeter than honey", "the swarming bees bestow?", "Only one thing could be sweeter:", "your lips, I'd have you know."], "day": "02-13"}, {"slug": "kuca-u-masti", "title_hr": "Kuća u mašti", "title_en": "A House in My Imagination", "hr": ["U mašti gradim kuću.", "Samo za nas dvoje,", "da u njoj ostvarim", "sve divne snove moje."], "en": ["In fancy I'm building", "a house for us two,", "where all my fine dreams", "I can make come true."], "day": "02-14", "occ_hr": "Valentinovo · napisano na današnji dan, 1974.", "occ_en": "Valentine's Day · written on this day in 1974"}, {"slug": "sokacki-obicaji", "title_hr": "Šokački običaji", "title_en": "Šokac Customs", "hr": ["Volim prela, sijela, šokačke divane,", "i maškare volim, kada se opreme.", "svu ljepotu volim u svatovske dane,", "divne običaje što žive kroz vrijeme."], "en": ["I love the spinning bees, sijela, the Šokac yarns,", "I love the masqueraders, when dressed up they appear;", "I love all the beauty of wedding-feast days,", "the wonderful customs that live year on year."], "day": "02-15"}, {"slug": "zasto-covjek-nije-kao-dijete", "title_hr": "Zašto čovjek nije kao dijete", "title_en": "Why Is Man Not Like a Child", "hr": ["Zašto čovjek nije kao dijete", "u čistoći svoje duše?", "Zašto neki kad odrastu", "sve vrline ljudske ruše?"], "en": ["Why is man not like a child", "in the pureness of his soul?", "Why do some, once they are grown,", "ruin every virtue known?"], "day": "02-16"}, {"slug": "vrati-mi-snove", "title_hr": "Vrati mi snove!", "title_en": "Give Me Back My Dreams!", "hr": ["Vrati mi se danas,", "da ne plačem sutra.", "Bez ljubavi tvoje", "tužna su mi jutra."], "en": ["Come back to me today,", "so I won't weep tomorrow.", "Without your love, my mornings", "are mornings full of sorrow."], "day": "02-17", "occ_hr": "napisano na današnji dan, 1975.", "occ_en": "written on this day in 1975"}, {"slug": "djecji-snovi", "title_hr": "Dječji snovi", "title_en": "Children's Dreams", "hr": ["Čujte samo malog Vladu!", "Dobio od svoga brata", "s lješnjacima čokoladu", "veliku k´o sobna vrata."], "en": ["Listen, now, to little Vlado!", "From his brother he got, what's more,", "chocolate bar with hazelnuts", "big as a bedroom door!"], "day": "02-18"}, {"slug": "od-djetinjstva-do-starackih-dana", "title_hr": "Od djetinjstva do staračkih dana", "title_en": "From Childhood to Old Age", "hr": ["Proš'o Božić i godina Nova,", "odjurio i Valentin sveti,", "a godine na pleća se nižu,", "jer nam život kao strijela leti."], "en": ["Christmas gone, the New Year gone as well,", "and Saint Valentine has hurried by;", "years keep piling up upon our shoulders,", "for our life, just like an arrow, flies."], "day": "02-19", "occ_hr": "napisano na današnji dan, 2010.", "occ_en": "written on this day in 2010"}, {"slug": "snjezana", "title_hr": "Snježana", "title_en": "Snježana", "hr": ["Da li si od snježnih pahuljica", "ili od perja rajske ptice?", "Ili leptir krilima je nježno", "milovao tvoje divno lice?"], "en": ["Are you made of flakes of snow,", "or of plumes from a bird of paradise?", "Or did a butterfly, with gentle wings,", "tenderly caress your lovely face?"], "day": "02-20", "occ_hr": "napisano na današnji dan, 1989.", "occ_en": "written on this day in 1989"}, {"slug": "da-spasimo-stare-obicaje", "title_hr": "Da spasimo stare običaje", "title_en": "Let Us Save the Old Customs", "hr": ["Kada zima dođe, bilo je veselo,", "skupljale se cure s večeri na prelo.", "Bećari bi došli curama na sijelo,", "veselo je zimi bilo svako selo."], "en": ["When winter came, it was a merry season:", "of evenings girls would gather at the prelo,", "the bećars came to join them at the sijelo,", "and every village, winter-long, was merry."], "day": "02-21"}, {"slug": "uloga-zene-u-braku", "title_hr": "Uloga žene u braku", "title_en": "A Wife's Role in Marriage", "hr": ["Sto poslova žena u kući ima,", "trči po cijeli dan.", "Šije, pere, kuha, sprema,", "dok je ne savlada san."], "en": ["A hundred jobs she has at home,", "she's on the run all day;", "she sews, she washes, cooks and cleans,", "till sleep bears her away."], "day": "02-22", "occ_hr": "napisano na današnji dan, 2009.", "occ_en": "written on this day in 2009"}, {"slug": "zecic-ocalinko", "title_hr": "Zečić Očalinko", "title_en": "Specky the Bunny", "hr": ["Gledam jednog zečića,", "naočale ima.", "Zbog toga je, vjerujte,", "mrkva bila kriva."], "en": ["I'm watching a young bunny", "who has glasses on;", "the carrot was to blame for it,", "believe me, everyone."], "day": "02-23"}, {"slug": "jozi-dubrovicu", "title_hr": "Jozi Dubroviću", "title_en": "To Jozo Dubrović", "hr": ["Želim da nam knjiga ova", "Divno prijateljstvo spaja.", "Družiti se, ta ljepota,", "Stvara ljudskoj duši sjaja."], "en": ["May this book of ours, I pray,", "bind us in a friendship fine.", "Keeping company — such beauty —", "makes the human spirit shine."], "day": "02-24", "occ_hr": "napisano na današnji dan, 2013.", "occ_en": "written on this day in 2013"}, {"slug": "djeca-snjeska-napravila", "title_hr": "Djeca snješka napravila", "title_en": "The Children Made a Snowman", "hr": ["Pa je snješko tužan bio,", "od tuge se rastopio.", "Mrkva, ugljan, metla stoje:", "što od snješka ostalo je."], "en": ["Then the snowman grew so sad,", "melted from the grief he had.", "Carrot, coal and broom stay on:", "all that's left, now he is gone."], "day": "02-25"}, {"slug": "dva-potoka-dvije-rijeke", "title_hr": "Dva potoka, dvije rijeke", "title_en": "Two Streams, Two Rivers", "hr": ["Na svom putu u prirodi,", "svaka voda teče vodi,", "pa se tako sve po malo,", "iz potoka rijeka rodi."], "en": ["On its journey, out in nature,", "every water runs to water;", "bit by bit, and so it goes,", "from the stream a river grows."], "day": "02-26"}, {"slug": "ljubav-nekada-i-sada", "title_hr": "Ljubav nekada i sada", "title_en": "Love Then and Now", "hr": ["Sada više ne kaže:", "\"Oh, mužiću zdravo!\"", "Već u bradu promrsi:", "\"Odnio te đavo!\""], "en": ["She no longer says,", "\"Oh, hubby, hello!\"", "But mutters under her breath:", "\"To the devil you go!\""], "day": "02-27"}, {"slug": "visibaba", "title_hr": "Visibaba", "title_en": "The Snowdrop", "hr": ["Visibaba nježna, mala,", "prevarila ljubičicu:", "uzela je lopaticu", "i snijeg bijeli razbacala,", "prije nje je procvjetala."], "en": ["Little snowdrop, frail and small,", "played the violet a trick:", "took a little shovel, quick,", "flung away the white snowfall,", "and bloomed before her, first of all."], "day": "02-28"}, {"slug": "zbrkani-snovi", "title_hr": "Zbrkani snovi", "title_en": "Muddled Dreams", "hr": ["Slušajte me, djeco, sada:", "probudih se jednog jutra,", "mjesto zore suton pada –", "mislim da je bilo sutra."], "en": ["Listen, children, what I say:", "I woke up one morning, when", "dusk instead of dawn held sway;", "I think it was tomorrow then."], "day": "02-29"}, {"slug": "dragi-prijatelji", "title_hr": "Dragi prijatelji!", "title_en": "Dear Friends!", "hr": ["To drugarstvo koje traje,", "da se nikad ne ugasi,", "neka ova pjesma bude,", "plamen da ju vječno spasi!"], "en": ["This companionship that lasts,", "so that it may never fade,", "let this poem be a flame", "by which it is ever saved!"], "day": "03-01", "occ_hr": "napisano na današnji dan, 2013.", "occ_en": "written on this day in 2013"}, {"slug": "sretan-ti-rodendan", "title_hr": "Sretan ti rođendan", "title_en": "Happy Birthday to You", "hr": ["U životu sretna bila", "bez imalo tužne sjene.", "A najljepše kad ti bude,", "ti se onda sjeti mene."], "en": ["May your life be happy, free", "of the slightest shade of sorrow;", "when your days are at their fairest,", "then, my dear, remember me."], "day": "03-02", "occ_hr": "napisano na današnji dan, 1974.", "occ_en": "written on this day in 1974"}, {"slug": "lastavica", "title_hr": "Lastavica", "title_en": "The Swallow", "hr": ["Lasto, ptico mila", "proljeća vjesniče!", "Jesi li umorna", "od dugoga leta?"], "en": ["Swallow, bird so dear,", "herald of the spring!", "Are you tired now", "from your lengthy flight?"], "day": "03-03"}, {"slug": "majka", "title_hr": "Majka", "title_en": "Mother", "hr": ["Kada dijete noću plače,", "iz snova kada se budi,", "da čedu svome utjehu nađe,", "majka ga svija na grudi."], "en": ["When a child cries in the night,", "waking from its dreams in fright,", "mother, to console her little one,", "holds it to her bosom tight."], "day": "03-04", "occ_hr": "napisano na današnji dan, 1980.", "occ_en": "written on this day in 1980"}, {"slug": "uloga-zene-u-braku", "title_hr": "Uloga žene u braku", "title_en": "A Wife's Role in Marriage", "hr": ["Kada muža glava zaboli,", "kada treba problem da riješi.", "Žena je tu da mu utjehu pruži", "i da ga nježno tješi."], "en": ["When the husband has a headache,", "when some problem he must address,", "the wife is there to give him comfort", "and soothe him with tenderness."], "day": "03-05"}, {"slug": "sretna-proljeca", "title_hr": "Sretna proljeća", "title_en": "Happy Springtimes", "hr": ["Jednog dana ozari me sunce,", "ozari me i sunce i sreća.", "Poljupcima koje si mi dala,", "sretna su mi svanula proljeća."], "en": ["One day I was lit up by the sun,", "lit up by the sun and by delight;", "with the kisses that you gave to me,", "happy springtimes dawned for me, so bright."], "day": "03-06"}, {"slug": "sokadijo-moj-voljeni-kraju", "title_hr": "Šokadijo moj voljeni kraju", "title_en": "Šokadija, My Beloved Land", "hr": ["Slavonijo moj mirisni cvijetu,", "najljepša si na čitavom svijetu.", "Nikada te neću nikom dati,", "vječito ću tebe svojom zvati."], "en": ["Slavonia, my fragrant flower, you", "are loveliest the whole wide world through;", "I'll never give you up to anyone —", "forever I shall call you mine alone."], "day": "03-07", "occ_hr": "napisano na današnji dan, 2014.", "occ_en": "written on this day in 2014"}, {"slug": "zena", "title_hr": "Žena", "title_en": "Woman", "hr": ["Žena je najljepša bajka,", "Kao sestra,", "Kao supruga,", "Kao majka."], "en": ["Woman is the loveliest fairy tale,", "as a sister,", "as a wife,", "as a mother."], "day": "03-08", "occ_hr": "Dan žena", "occ_en": "International Women's Day"}, {"slug": "gliste", "title_hr": "Gliste", "title_en": "The Worms", "hr": ["A kad zima mine", "i kad sunce sine,", "kad nestanu rose –", "mogu noge bose!“"], "en": ["And once the winter's past", "and sunshine comes at last,", "and the dew is gone, and so,", "then barefoot you can go!\""], "day": "03-09"}, {"slug": "ima-li-sto-ljepse", "title_hr": "Ima li što ljepše", "title_en": "Is There Anything More Beautiful", "hr": ["Kada žena voli", "i kada je voljena,", "ona je Afrodita", "svome Adonisu."], "en": ["When a woman loves", "and when she is loved,", "she is Aphrodite", "to her Adonis."], "day": "03-10"}, {"slug": "duga", "title_hr": "Duga", "title_en": "The Rainbow", "hr": ["Kad kiša pada", "i sunce sije,", "to oblak vodu", "iz rijeke pije."], "en": ["When rain is falling", "and the sun's aglow,", "the cloud drinks water", "from the river below."], "day": "03-11"}, {"slug": "izmedu-htjenja-i-mogucnosti", "title_hr": "Između htjenja i mogućnosti", "title_en": "Between Wanting and Being Able", "hr": ["Naša mladost najljepše je doba,", "a ljubav je zato da se proba."], "en": ["Our youth, it is the loveliest time of all,", "and love is there for trying, after all."], "day": "03-12", "occ_hr": "napisano na današnji dan, 2004.", "occ_en": "written on this day in 2004"}, {"slug": "seljacke-idile", "title_hr": "Seljačke idile", "title_en": "Village Idylls", "hr": ["Sviće zora i sunašce viri,", "bez oblaka nebo čisto, plavo,", "kroz dolinu lahor tiho piri,", "za sjetvu je danas vrijeme pravo."], "en": ["Dawn is breaking, and the sun peeps through,", "not a cloud — the sky is clean and blue,", "softly through the valley breathes the breeze,", "and the day is right for sowing, too."], "day": "03-13"}, {"slug": "haiku", "title_hr": "Haiku", "title_en": "Haiku", "hr": ["PROLJEĆE:", "Zima dala pete,", "topola baca perje,", "klepeću rode."], "en": ["Spring:", "Winter's taken to its heels,", "the poplar tosses feathers,", "the storks clatter."], "day": "03-14"}, {"slug": "u-mom-narucju", "title_hr": "U mom naručju", "title_en": "In My Arms", "hr": ["Kad milujem tebe, draga,", "meni ljepše sreće nije.", "Proljetne mi ruže cvatu", "i ljetno me sunce grije."], "en": ["When I stroke you, oh, my darling,", "there's no sweeter joy I know.", "Springtime roses bloom for me,", "and the summer sun warms me so."], "day": "03-15"}, {"slug": "sjecanje-na-djetinjstvo", "title_hr": "Sjećanje na djetinjstvo", "title_en": "Remembering My Childhood", "hr": ["I sad kad se sjetim srce me zazebe.", "Na svakom koraku, bijedu sam susreto.", "Nikada se nisam stidio sam sebe,", "jer poštenje meni bilo je presveto."], "en": ["And even now, when I recall it, my heart runs cold.", "At every step, it was misery I'd see;", "but I was never once ashamed — not me —", "for honesty was the most sacred thing I'd hold."], "day": "03-16", "occ_hr": "napisano na današnji dan, 1976.", "occ_en": "written on this day in 1976"}, {"slug": "televizor-prodajem-u-boji", "title_hr": "Televizor prodajem u boji", "title_en": "Colour TV for Sale", "hr": ["Na TV-u prava utakmica,", "pokraj tebe sjela i ženica,", "sretna guče, puna dobre volje.", "Pa zar može nešto biti bolje?"], "en": ["A proper match is on TV for you,", "your little wife sits down beside you too;", "she coos, so happy, in a merry mood —", "could anything be better? Nothing could!"], "day": "03-17"}, {"slug": "suha-kora-prove", "title_hr": "Suha kora prove", "title_en": "The Dry Crust of Cornbread", "hr": ["A kad shvatih tu razliku", "među ljudstvom što se rađa.", "I ta suha kora prove", "bila mi je tada slađa."], "en": ["And when I grasped the difference", "that is born among mankind,", "even that dry cornbread crust", "tasted sweeter, I would find."], "day": "03-18", "occ_hr": "napisano na današnji dan, 1976.", "occ_en": "written on this day in 1976"}, {"slug": "pjesma-sinu", "title_hr": "Pjesma sinu!", "title_en": "A Poem for My Son!", "hr": ["Ti još i ne znaš, kako bi i znao,", "koliko te moje biće silno voli,", "kada budeš svoje čedo sinom zvao", "tek ćeš onda znati za strepnje i boli."], "en": ["You do not know yet (how could you have known)", "how mightily my being loves you so;", "but when you call a son of yours your own,", "then only will you know the fear and woe."], "day": "03-19", "occ_hr": "Josipovo, Dan očeva", "occ_en": "St Joseph's Day, Father's Day"}, {"slug": "na-poklon-osnovnoj-skoli-sopje", "title_hr": "Na poklon Osnovnoj školi Sopje", "title_en": "A Gift to the Sopje Primary School", "hr": ["Našoj školi darujem tu knjigu,", "kao spomen mog djetinjstva znaci,", "kroz te pjesme ja ostavljam sebe,", "nek' je vide i budući đaci."], "en": ["I give this book to our school to keep,", "a keepsake of my childhood, as a sign;", "in these poems here I leave myself behind:", "may future pupils see me in each line."], "day": "03-20", "occ_hr": "napisano na današnji dan, 2013.", "occ_en": "written on this day in 2013"}, {"slug": "pjesnikova-zelja", "title_hr": "Pjesnikova želja", "title_en": "The Poet's Wish", "hr": ["JA VAM DJECO DONOSIM PROLJEĆE", "TOPLO VRIJEME I MIRISNO CVIJEĆE!"], "en": ["To you, dear children, springtime's what I bring:", "warm weather, fragrant flowers blossoming!"], "day": "03-21", "occ_hr": "Svjetski dan poezije i prvi dan proljeća · napisano na današnji dan, 2011.", "occ_en": "World Poetry Day, first day of spring · written on this day in 2011"}, {"slug": "trazim-janjce-za-kucne-ljubimce", "title_hr": "Tražim janjce za kućne ljubimce", "title_en": "Wanted: Lambs as Pets", "hr": ["Divne kuće, u dvorištu cvijeće,", "ispred kuće Karašica teče."], "en": ["Lovely houses, in the yard the flowers grow,", "before the house the Karašica flows."], "day": "03-22", "occ_hr": "napisano na današnji dan, 2007.", "occ_en": "written on this day in 2007"}, {"slug": "trac", "title_hr": "Trač", "title_en": "Gossip", "hr": ["Ja vas molim i ljudi i žene,", "počistite ispred svoga praga,", "ne tražite sad okolo vraga,", "Ostavite vi na miru mene."], "en": ["Men and women, this I beg of you:", "sweep before your own threshold, clean and clear,", "don't go hunting for the devil round here,", "and just leave me in peace — that's all you need do."], "day": "03-23"}, {"slug": "odgovor-drenovcanke", "title_hr": "Odgovor Drenovčanke", "title_en": "The Drenovci Woman's Reply", "hr": ["Reći ću ti što bih htjela:", "da polako život teče,", "u životu mome bolnom,", "puno zdravlja, malo sreće."], "en": ["I will tell you what I'd want:", "for my life to flow its way", "slowly, and in all my pain,", "lots of health, some joy, I pray."], "day": "03-24", "occ_hr": "napisano na današnji dan, 2007.", "occ_en": "written on this day in 2007"}, {"slug": "djeda-daje-knjigu-svom-unuku", "title_hr": "Djeda daje knjigu svom unuku!", "title_en": "Grandpa Gives a Book to His Grandson!", "hr": ["Kada djedu u zagrljaj kreće,", "djeda će ga staviti u krilo.", "Obadva će blistati od sreće,", "oko srca bit će njima milo."], "en": ["When he sets off to run to Grandpa's hug,", "then Grandpa lifts him up onto his knee;", "the pair of them will glow with happiness,", "and warm around their hearts they both will be."], "day": "03-25", "occ_hr": "napisano na današnji dan, 2013.", "occ_en": "written on this day in 2013"}, {"slug": "sretna-proljeca", "title_hr": "Sretna proljeća", "title_en": "Happy Springtimes", "hr": ["Ne znam gdje si do sad bila, draga.", "Da l' pod snijegom k'o ljubica mala?"], "en": ["Where you were till now, my dear, I do not know —", "under snow, a little violet, could it be?"], "day": "03-26"}, {"slug": "moja-velika-otkrica", "title_hr": "Moja velika otkrića", "title_en": "My Great Discoveries", "hr": ["Htio sam svijetu", "sve najbolje dati,", "al´ me nije moja", "razumjela mati."], "en": ["I wanted to give", "the world all that's good,", "but my own mother", "never understood."], "day": "03-27"}, {"slug": "valpovacke-poete", "title_hr": "Valpovačke poete", "title_en": "Valpovo's Poets", "hr": ["Kad napiše svoju knjigu,", "pjesniku je svakom dika", "pa i onda, kad ga nema,", "ostala je časna slika."], "en": ["When he's written his own book,", "every poet's proud, each one;", "even later, when he's gone,", "an honoured image lingers on."], "day": "03-28", "occ_hr": "napisano na današnji dan, 2007.", "occ_en": "written on this day in 2007"}, {"slug": "proljece", "title_hr": "Proljeće", "title_en": "Spring", "hr": ["Okopnio snijeg,", "proljeće je stiglo.", "Sluti se toplina sunca.", "Trava polako rosu pije,", "djetlić već drvo kljuca."], "en": ["The snow has thawed,", "and spring is here.", "One senses the warmth of the sun.", "The grass drinks slowly of the dew,", "the woodpecker's tapping has begun."], "day": "03-29"}, {"slug": "kitisanci", "title_hr": "Kitišanci", "title_en": "Kitišanci", "hr": ["Oh, posveti, Bože ruke,", "koje su ti hram dizali,", "da bi naša pokoljenja,", "za blagoslov božji znali."], "en": ["Sanctify, O Lord, the hands", "that have raised this house to you,", "so our generations after", "may know of God's blessing too."], "day": "03-30"}, {"slug": "slikar-zeko", "title_hr": "Slikar zeko", "title_en": "Bunny the Painter", "hr": ["Jutros se u dvorištu", "digla strašna graja,", "jer netko je kokicama", "ofarbao jaja."], "en": ["In the yard this very morning", "such a racket rose — and why?", "Someone went and painted all", "of the hens' eggs, on the sly."], "day": "03-31"}, {"slug": "rodendan-ti-sretan-zelim-franjo", "title_hr": "Rođendan ti sretan želim Franjo!", "title_en": "A Happy Birthday to You, Franjo!", "hr": ["Kroz Tvoj život nek' se ljubav kreće,", "u tvom radu Bog Ti dao sreće,", "na Tvom putu cvjetalo Ti cvijeće,", "jer nam život bez povratka teče."], "en": ["Through all your life may love go where you go,", "and in your work may God His luck bestow,", "along your path may flowers bloom and grow,", "for life flows on, and back it cannot flow."], "day": "04-01", "occ_hr": "napisano na današnji dan, 2014.", "occ_en": "written on this day in 2014"}, {"slug": "jeka", "title_hr": "Jeka", "title_en": "Echo", "hr": ["Volim te, volim te, volim!", "Taj odjek divne jeke,", "u srcu mi snažno bruji,", "k'o žubor gorske rijeke."], "en": ["I love you, love you, love you!", "That lovely echo's ring", "hums strongly in my heart", "like mountain waters murmuring."], "day": "04-02", "occ_hr": "napisano na današnji dan, 1979.", "occ_en": "written on this day in 1979"}, {"slug": "maslacak", "title_hr": "Maslačak", "title_en": "The Dandelion", "hr": ["Procvao maslačak", "žuti se u travi,", "a kasnije nosi", "pahulje na glavi."], "en": ["The dandelion's blooming,", "yellow in the grass,", "and fluff sits on its head", "later, as days pass."], "day": "04-03"}, {"slug": "zivot-penzionera", "title_hr": "Život penzionera", "title_en": "A Pensioner's Life", "hr": ["A izbori kada prođu,", "nastavlja se priča stara.", "Penzioner k'o i prije", "mali je k'o bubamara."], "en": ["When elections have gone by,", "it's the old tale, as you've heard:", "and the pensioner, as ever,", "is as small as a ladybird."], "day": "04-04", "occ_hr": "napisano na današnji dan, 1992.", "occ_en": "written on this day in 1992"}, {"slug": "katici-eper-i-marici-opancar", "title_hr": "Katici Eper i Marici Opančar", "title_en": "To Katica Eper and Marica Opančar", "hr": ["Prošao je život kao rijeka", "i odnio dio naših snova."], "en": ["Life has gone by the way a river goes,", "and carried off a portion of our dreams."], "day": "04-05"}, {"slug": "brodolomac", "title_hr": "Brodolomac", "title_en": "The Castaway", "hr": ["Ja opet živim, gledam žarko sunce", "i jutarnju rosu kako trava pije.", "I dalje moje spavalo bi srce,", "da ga tvoja ljubav probudila nije."], "en": ["I live again; I see the blazing sun above,", "and how the grass drinks in the morning dew so deep;", "and still this heart of mine would lie there fast asleep", "if it had never been awakened by your love."], "day": "04-06", "occ_hr": "napisano na današnji dan, 1975.", "occ_en": "written on this day in 1975"}, {"slug": "kalendar", "title_hr": "Kalendar", "title_en": "The Calendar", "hr": ["U ožujku visibaba", "ispod snijega izviruje.", "U travnju već trava raste", "i cvrkut se ptica čuje."], "en": ["March, and there's the snowdrop peeping", "out from underneath the snow.", "April, and the grass is growing,", "birds are chirping, high and low."], "day": "04-07"}, {"slug": "za-uskrs-se-farba-jaje", "title_hr": "Za Uskrs se farba jaje", "title_en": "At Easter We Dye the Eggs", "hr": ["Eto nam se Uskrs javlja,", "bit će dječici veselja,", "jaja ćemo ofarbati,", "to je naša draga želja."], "en": ["Easter's here, it's come to call,", "little children will be glad;", "we'll be dyeing eggs, and that", "is the dearest wish we've had."], "day": "04-08", "occ_hr": "uskrsno vrijeme", "occ_en": "Eastertide"}, {"slug": "sokacki-obicaji", "title_hr": "Šokački običaji", "title_en": "Šokac Customs", "hr": ["Volim kad se ljubav sokacima vodi.", "Volim škripu đerma i seosku viku.", "Volim kada mjesec sa zvijezdama hodi,", "na toj mjesečini volim svoju diku."], "en": ["I love it when lovers go walking the lanes,", "I love the well-sweep's creaking, the shouts down the street,", "I love when the moon strolls along with the stars,", "and there in that moonlight I love my own sweet."], "day": "04-09", "occ_hr": "napisano na današnji dan, 1994.", "occ_en": "written on this day in 1994"}, {"slug": "postovani-prijatelju", "title_hr": "Poštovani prijatelju!", "title_en": "Dear Friend!", "hr": ["U proljeće mnoge žabe,", "u bari su kreketale.", "Da se riješi žablji problem,", "sastanak su održale."], "en": ["In the springtime, many frogs", "croaked there in the pond all day;", "to resolve the frogs' dilemma", "they held a meeting right away."], "day": "04-10"}, {"slug": "sve-se-caje-okupise", "title_hr": "Sve se \"Čaje\" okupiše", "title_en": "All of Čaje Gathered Here", "hr": ["Kad svirači zasviraju znano,", "NE BUDI ME, MAJKO, TAKO RANO,", "To mi vrati onu ljubav staru,", "pa zaigra srce u bećaru."], "en": ["When players strike that tune so widely known,", "\"Don't Wake Me Early, Mother\", all my own,", "it brings me back that old love, as before,", "and in this bećar my heart dances once more."], "day": "04-11", "occ_hr": "napisano na današnji dan, 2013.", "occ_en": "written on this day in 2013"}, {"slug": "proljece", "title_hr": "Proljeće", "title_en": "Spring", "hr": ["Zatim u žaru zapadu ide", "još jedan proljetni dan.", "Zvijezde na nebu", "već se pale,", "slatki nam donose san."], "en": ["Then, glowing, off into the west", "goes one more day of spring.", "The stars up in the sky", "are lighting up already,", "sweet sleep to us they bring."], "day": "04-12"}, {"slug": "pod-granama-jorgovana", "title_hr": "Pod granama jorgovana", "title_en": "Beneath the Lilac Boughs", "hr": ["Pod granama jorgovana,", "u zvjezdanoj tihoj noći,", "dok je ruža mirisala,", "ljubio sam tvoje oči."], "en": ["Underneath the lilac branches,", "in the hush of starry skies,", "while the rose was breathing fragrance,", "I was kissing your dear eyes."], "day": "04-13"}, {"slug": "slikar-zeko", "title_hr": "Slikar zeko", "title_en": "Bunny the Painter", "hr": ["Mislim da je svima jasno", "tko je majstor bio.", "Eto, djeco, to je zeko", "jaja obojio."], "en": ["I think it's clear to everyone", "who the master was that day.", "There, dear children: it was bunny", "who had painted them that way."], "day": "04-14"}, {"slug": "edukacija-o-vocarstvu", "title_hr": "Edukacija o voćarstvu", "title_en": "A Lesson in Fruit-Growing", "hr": ["Na praksu je on prešao tada,", "Jednu voćku obrezo' je jako.", "Grane lete, oh, tako mu jada,", "Nisam znao da se može tako."], "en": ["Then he moved on to practice, straight away,", "and cut one fruit tree back, and cut it hard.", "The branches flew! Oh, dear me, what dismay!", "I'd no idea that pruning went so far."], "day": "04-15", "occ_hr": "napisano na današnji dan, 2004.", "occ_en": "written on this day in 2004"}, {"slug": "kad-ispuni-televizor-zelje", "title_hr": "Kad ispuni televizor želje", "title_en": "When the Television Grants Wishes", "hr": ["Svako mjesto tamburaša ima,", "Slavoniji ljepotu su dali,", "glazbom srca otvorili svima,", "Šokadiju svirkom uljepšali."], "en": ["Each place has its own tamburica band;", "they gave Slavonia beauty with their art;", "with music they have opened every heart", "and made Šokadija a lovelier land."], "day": "04-16", "occ_hr": "napisano na današnji dan, 2013.", "occ_en": "written on this day in 2013"}, {"slug": "etno-kuca-semialjac-kate", "title_hr": "Etno kuća Semialjac Kate", "title_en": "Kata Semialjac's Ethno House", "hr": ["Iza štaglja predivna ljepota,", "zrak miriše, procvalo je voće,", "noć je topla, divna mjesečina,", "a zvijezde su okitile veče'."], "en": ["Behind the barn, a loveliness so rare:", "the air is fragrant, fruit trees are in flower,", "the night is warm, the moonlight is divine,", "and all the stars have decked the evening hour."], "day": "04-17"}, {"slug": "lijepo-je-biti-voljen", "title_hr": "Lijepo je biti voljen", "title_en": "It's Lovely to Be Loved", "hr": ["Lijepo je biti voljen", "i kada iskreno ljubiš.", "Kada svoje tople usne", "voljenom biću nudiš."], "en": ["It is lovely to be loved,", "and to love sincerely too,", "when you offer your warm lips", "to the one who's loved by you."], "day": "04-18"}, {"slug": "nudim-finu-sljivovicu", "title_hr": "Nudim finu šljivovicu", "title_en": "Fine Plum Brandy on Offer", "hr": ["Najviše se ona voli,", "kada nekog zub zaboli,", "bilo koji, nema veze,", "makar onaj iz proteze."], "en": ["It is loved the most, I've found,", "when a toothache comes around;", "any tooth at all will do,", "even one from dentures, too."], "day": "04-19"}, {"slug": "poezijski-rad-kroz-zivot", "title_hr": "Poezijski rad kroz život", "title_en": "A Life's Work in Poetry", "hr": ["Šezdeset je ljeta prošlo,", "od kada sam napisao:", "„NE BUDI ME, MAJKO, RANO,", "JOŠ SE NISAM NASPAVAO“."], "en": ["Sixty summers now have passed", "since the day that first I wrote:", "\"MOTHER, DO NOT WAKE ME EARLY,", "I AM NOT YET RESTED, NO.\""], "day": "04-20"}, {"slug": "kratki-dani", "title_hr": "Kratki dani", "title_en": "Short Days", "hr": ["Blagi pogled oka tvoga", "i obrazi nježni tvoji,", "kad ih ljubim, cvijete mili,", "prekratki su dani moji."], "en": ["Gentle glances of your eyes", "and your cheeks so soft and fine —", "when I kiss them, darling flower,", "all too short these days of mine."], "day": "04-21", "occ_hr": "napisano na današnji dan, 2014.", "occ_en": "written on this day in 2014"}, {"slug": "sto-je-ljubav", "title_hr": "Što je ljubav?", "title_en": "What Is Love?", "hr": ["Ljubav je,", "vjetrom nošen", "lutajući brod,", "koji muškarca vodi", "u bračnu luku.", "Kad progleda,", "tek tada vidi", "da je nasukan."], "en": ["Love is", "a wandering ship,", "borne by the wind,", "that leads a man", "into the harbour of marriage.", "When his eyes open,", "only then does he see", "that he has run aground."], "day": "04-22", "occ_hr": "napisano na današnji dan, 1997.", "occ_en": "written on this day in 1997"}, {"slug": "pod-krosnjom-kestena", "title_hr": "Pod krošnjom kestena", "title_en": "Under the Chestnut's Crown", "hr": ["Kad proljetno sunce grane,", "svako drvo tad procvjeta", "i opojni miris širi,", "što je ukras ovog svijeta."], "en": ["When the sun of spring shines down,", "every tree bursts into flower", "and spreads heady scent around", "that adorns this world of ours."], "day": "04-23"}, {"slug": "slavonija", "title_hr": "Slavonija", "title_en": "Slavonia", "hr": ["U edenu tom zemaljskom,", "eto, tu sam rođen i ja.", "Tu življahu moji preci:", "to je moja Slavonija!"], "en": ["In this earthly Eden, here,", "there, you see, I too was born.", "Here my forefathers once lived:", "this is my Slavonia!"], "day": "04-24"}, {"slug": "dodi-na-moje-grudi", "title_hr": "Dođi na moje grudi", "title_en": "Come to My Breast", "hr": ["Kada prođe cvijet mladosti", "i starost polako se nudi,", "da nađeš ljubav kao žena,", "dođi na moje grudi!"], "en": ["When the flower of youth is over", "and old age slowly comes as guest,", "so that you find love as a woman,", "come to my breast!"], "day": "04-25"}, {"slug": "oj-dodo-oj-dodole", "title_hr": "Oj, dodo, oj, dodole", "title_en": "Oj, Dodo, Oj, Dodole", "hr": ["Daj nam, Bože, kiše malo,", "da natopi žedno polje,", "da se malo živi bolje."], "en": ["Give us, Lord, a little rain,", "soak the thirsty field again,", "so we'll live a little better."], "day": "04-26", "occ_hr": "napisano na današnji dan, 1998.", "occ_en": "written on this day in 1998"}, {"slug": "jutarnji-problemi", "title_hr": "Jutarnji problemi", "title_en": "Morning Troubles", "hr": ["Dok djeca spavaju,", "cipelice ustaju,", "po dvorištu trče", "i loptu šutaju."], "en": ["While the children sleep,", "the shoes get out of bed,", "race around the yard", "and play football instead."], "day": "04-27"}, {"slug": "lastina-kuca", "title_hr": "Lastina kuća", "title_en": "The Swallow's House", "hr": ["U svako pramaljeće", "nama se laste jave.", "Gnijezdo kad brižno srede,", "jaja u njega stave."], "en": ["Every single springtime", "the swallows greet us again;", "once they've tidied the nest with care,", "they lay their eggs in it then."], "day": "04-28"}, {"slug": "kao-nekad-nismo-vise-mladi", "title_hr": "Kao nekad nismo više mladi", "title_en": "We're No Longer Young as Once We Were", "hr": ["Kao nekad nismo više mladi.", "Sretnih dana neka bude više", "i starački nek' nas minu jadi", "i veselja da se lakše diše."], "en": ["We are no longer young, as once we were.", "May happy days be many, more and more,", "and may the woes of old age pass us by,", "and joy, so we breathe easier than before."], "day": "04-29"}, {"slug": "dravsko-proljece", "title_hr": "Dravsko proljeće", "title_en": "Drava Spring", "hr": ["Tridesetog travnja Sopje", "spretno veze kolo sreće,", "jer Sopjani toga dana", "slave „DRAVSKO PRAMALJEĆE“."], "en": ["On the thirtieth of April", "Sopje deftly weaves joy's ring,", "since upon that day its people", "celebrate the \"Drava Spring\"."], "day": "04-30", "occ_hr": "Dravsko proljeće u Sopju", "occ_en": "Drava Spring festival in Sopje"}, {"slug": "lopata-i-kramp", "title_hr": "Lopata i kramp", "title_en": "The Shovel and the Pick", "hr": ["Lopata i stari kramp,", "svakog dana složno rade:", "zajednički cestu grade,", "često puta trnje vade,", "a ponekad ruže sade.", "A sve rade bez nagrade!"], "en": ["The shovel and the old pick", "work in concord every day:", "together they build the road,", "often clear the thorns away,", "and plant roses along the way.", "And all of this without pay!"], "day": "05-01", "occ_hr": "Praznik rada", "occ_en": "Labour Day"}, {"slug": "nek-se-slavi-u-sopju-veselje", "title_hr": "Nek' se slavi u Sopju veselje", "title_en": "Let Sopje Celebrate and Make Merry", "hr": ["U proljeće MAJIPANI se sade,", "to mladići znak curama daju,", "jer ujesen svatovi se prave,", "neka budu spremne za udaju."], "en": ["In spring they plant the maypoles in the ground:", "the young men give the girls a sign this way,", "for in the autumn weddings will be held,", "so let them be prepared for their wedding day."], "day": "05-02"}, {"slug": "proljece", "title_hr": "Proljeće", "title_en": "Spring", "hr": ["Mušice lete i pčele zuje,", "posvuda miriše cvijet.", "Da ptićima svojim", "hranu nađu,", "krenule laste na let."], "en": ["Gnats are flying, bees are humming,", "flowers smell sweet everywhere.", "To find some food", "for their young chicks,", "off fly the swallows through the air."], "day": "05-03"}, {"slug": "dakovo-je-biser-slavonije", "title_hr": "Đakovo je biser Slavonije", "title_en": "Đakovo Is the Pearl of Slavonia", "hr": ["Slavonijo, domovino moja,", "volim tebe k'o majčino krilo."], "en": ["Slavonia, my homeland and my own,", "I love you like my mother's lap, so dear."], "day": "05-04"}, {"slug": "osa", "title_hr": "Osa", "title_en": "The Wasp", "hr": ["Kao zumbul plavi", "miriše joj kosa.", "Ja sletoh na cvjetak", "i postadoh osa."], "en": ["Her hair has the scent", "of a hyacinth blue;", "I lit on the blossom,", "and a wasp I grew."], "day": "05-05"}, {"slug": "duga", "title_hr": "Duga", "title_en": "The Rainbow", "hr": ["Jeste li vidjeli", "na nebu dugu,", "onu divnu", "šarenu prugu?"], "en": ["Have you ever seen", "the rainbow in the sky,", "that lovely stripe", "of colours, way up high?"], "day": "05-06"}, {"slug": "kratki-dani", "title_hr": "Kratki dani", "title_en": "Short Days", "hr": ["U krilu se tvome topim,", "k'o jutarnje rose majske."], "en": ["In your lap I melt away", "like the morning dew of May."], "day": "05-07"}, {"slug": "san-o-sreci", "title_hr": "San o sreći", "title_en": "A Dream of Happiness", "hr": ["Budila me moja majka,", "svako jutro zorimice", "i suzama svojim toplim,", "umivala moje lice."], "en": ["My own mother used to wake me", "every morning, at dawn's first trace,", "and with her own tears, so warm,", "she would wash my little face."], "day": "05-08"}, {"slug": "klokan", "title_hr": "Klokan", "title_en": "The Kangaroo", "hr": ["Klokana nježnog, malog,", "kad rujna zora zarudi,", "dok u toploj torbi spava,", "majčino srce budi."], "en": ["The tender little kangaroo,", "when dawn is flushing red,", "is woken by his mother's heart", "while in his warm pouch-bed."], "day": "05-09"}, {"slug": "majka", "title_hr": "Majka", "title_en": "Mother", "hr": ["Za svaku bolest čeda svoga,", "majčino srce pati.", "Svoje bi oči za njega dala.", "To može samo mati."], "en": ["For each illness of her child", "a mother's heart aches through and through.", "She would give her eyes for it —", "that, a mother alone can do."], "day": "05-10", "occ_hr": "Majčin dan (svibanj)", "occ_en": "Mother's Day (May)"}, {"slug": "uslisi-me-boze", "title_hr": "Usliši me, Bože", "title_en": "Hear Me, O God", "hr": ["Pa kad uđu kojima je dato,", "znam da ću i ja imati sreće", "i meni ćeš mjesta dati zato,", "jer srce je Tvoje od neba veće!"], "en": ["And when they've entered, those to whom it's given,", "I know that I'll be lucky, by and by,", "and You will give me, too, a place in heaven,", "because Your heart is bigger than the sky!"], "day": "05-11", "occ_hr": "Obljetnica pjesnikove smrti (2015.)", "occ_en": "Anniversary of the poet's death (2015)"}, {"slug": "mali-ivica", "title_hr": "Mali Ivica", "title_en": "Little Ivica", "hr": ["Pa mu sada mama", "nos i usta miva,", "njemu mrlja žao", "i plače za njima!"], "en": ["So now his mum is washing", "his nose and mouth for him,", "but he's sorry for the smudges,", "and he cries for them!"], "day": "05-12"}, {"slug": "sjecanje-na-djetinjstvo", "title_hr": "Sjećanje na djetinjstvo", "title_en": "Remembering My Childhood", "hr": ["Koru suhe prove svaki dan sam grizo.", "Da se može bolje, nisam mog'o znati,", "ipak nisam nikom u životu gmiz'o.", "Tako me je moja naučila mati."], "en": ["Each day I'd gnaw a crust of dry cornbread;", "that one could live much better, I could not know;", "yet never in my life have I crawled to anyone —", "that's how my mother taught me, long ago."], "day": "05-13"}, {"slug": "etno-kuca-zelcin", "title_hr": "Etno kuća Zelčin", "title_en": "The Ethno House at Zelčin", "hr": ["Tu kolijevka stoji u buđaku,", "dične ljude ona je zibala,", "pokoljenja mnoga iznjedrila,", "dok im majka pjesmicu pjevala."], "en": ["The cradle stands there in its corner nook,", "it rocked fine folk to sleep in days gone by,", "brought forth so many generations, while", "their mother sang to them a lullaby."], "day": "05-14"}, {"slug": "netaknuta-ruza", "title_hr": "Netaknuta ruža", "title_en": "The Untouched Rose", "hr": ["Uzmi od života ono što je tvoje,", "jer za sretnu ljubav trebaju tek dvoje."], "en": ["Take what is yours from life, take what is due,", "for happy love, all that it takes is two."], "day": "05-15"}, {"slug": "u-veselom-drustvu", "title_hr": "U veselom društvu", "title_en": "In Merry Company", "hr": ["\"Oprostite ima l'", "tu mjesta za mene?", "Ne samo za stolom,", "već u srcu vašem.\""], "en": ["\"Pardon me, is there", "a place here for me?", "Not just at your table,", "but within your heart.\""], "day": "05-16"}, {"slug": "na-cimenu-sokacko-veselje", "title_hr": "Na Čimenu Šokačko veselje", "title_en": "Šokac Merriment on the Čimen", "hr": ["Tu se skuplja Šokadija mlada", "biser naše Slavonije ravne", "da prikažu svu ljepotu sada", "uspomene iz prošlosti davne."], "en": ["Here gathers all the young Šokadija,", "the pearl of our Slavonia's level plain,", "to show us all its beauty now, and bring", "the memories of distant times again."], "day": "05-17", "occ_hr": "napisano na današnji dan, 2012.", "occ_en": "written on this day in 2012"}, {"slug": "sreca", "title_hr": "Sreća", "title_en": "Happiness", "hr": ["Male su ti i planete,", "misli među zvijezde lete.", "U ljubavi kad je sreće", "i sunce se rađa veće."], "en": ["Even planets seem too small,", "thoughts among the stars will fly;", "when there's happiness in love,", "the sun rises bigger in the sky."], "day": "05-18"}, {"slug": "protiv-svoje-volje", "title_hr": "Protiv svoje volje", "title_en": "Against My Will", "hr": ["I starost je polako već stigla,", "barem da je zdravlje malo bolje.", "Sada čekam na rajska blaženstva,", "vjerujte mi, protiv svoje volje."], "en": ["And now old age has slowly crept on in:", "if only I were not so often ill!", "And now I wait for heaven's blessed joys,", "believe me, friends, against my very will."], "day": "05-19"}, {"slug": "dravsko-proljece", "title_hr": "Dravsko proljeće", "title_en": "Drava Spring", "hr": ["Kad se kolo zavijori,", "noge pletu, sve se praši.", "Tankovito cura vrisne,", "običaji to su naši."], "en": ["When the kolo swirls and flutters,", "feet are weaving, dust flies high;", "shrill and thin a girl cries out:", "these are customs we live by."], "day": "05-20"}, {"slug": "pored-nase-rijeke", "title_hr": "Pored naše rijeke", "title_en": "Beside Our River", "hr": ["Od kada se nismo vidjeli nas dvoje?", "Možda te sad više prepoznao ne bi'?", "Godine su duge učinile svoje,", "a nekada mio bio sam ja tebi."], "en": ["How long since last we saw each other, we two?", "Perhaps I wouldn't know you now, if we met again?", "The long years that have passed have done what years will do,", "and once I used to be so dear to you, back then."], "day": "05-21"}, {"slug": "diljem-slavonije", "title_hr": "Diljem Slavonije", "title_en": "All Across Slavonia", "hr": ["Ja sam rođen u blizini Drave,", "u dolini polja i livada,", "okoline Podravske Slatine,", "Šokica me porodila mlada."], "en": ["I was born close by the Drava's banks,", "in the vale of the fields and meadows fair,", "in the country round Podravska Slatina;", "a young Šokica gave birth to me there."], "day": "05-22"}, {"slug": "zaspalo-mace", "title_hr": "Zaspalo mače", "title_en": "The Sleeping Kitten", "hr": ["Naša maca, kada spava,", "miče šapom, brkom,", "valjda miša tada sanja", "i hvata ga trkom."], "en": ["When our kitty is asleep,", "paw and whisker flick;", "she must dream she's chasing mice,", "running, oh so quick!"], "day": "05-23"}, {"slug": "hej-zivote", "title_hr": "Hej živote", "title_en": "Hey There, Life", "hr": ["Svim ljudima ovog svijeta,", "da im grana mira cvijeta!", "Ljudski razum da ne gube,", "da se kao braća ljube!"], "en": ["To all people of this world:", "may the branch of peace unfurl!", "May they keep their human mind,", "love like brothers, true and kind."], "day": "05-24", "occ_hr": "napisano na današnji dan, 1993.", "occ_en": "written on this day in 1993"}, {"slug": "ja-i-moj-medas-josip", "title_hr": "Ja i moj međaš Josip", "title_en": "Me and My Neighbour Josip", "hr": ["Stigli su nam i trenuci sreće,", "došlo vrijeme da se kući kreće.", "Domovino predivna i mila,", "uvijek si mi ti na srcu bila."], "en": ["Moments of good fortune came our way;", "the time had come to head back home to stay.", "Homeland, lovely, dear beyond compare,", "in my heart you always have been there."], "day": "05-25"}, {"slug": "dobro-dosli-prijatelji-dragi", "title_hr": "Dobro došli prijatelji dragi!", "title_en": "Welcome, My Dear Friends!", "hr": ["Mnogo ljeta iza mene stoji", "na plećima: sedamdeset devet.", "Koliko ću? Dragi Bogo znade,", "sve je dobro dok ne nađem krevet."], "en": ["Many a summer lies behind me now,", "upon my shoulders: seventy and nine.", "How many more? Dear God alone knows how;", "as long as I'm not bedridden, all is fine."], "day": "05-26"}, {"slug": "urednice-info-valpovstine", "title_hr": "Uredniče Info Valpovštine", "title_en": "To the Editor of INFO Valpovštine", "hr": ["Ja ću dalje stih pisati", "i ljepotu puku dati."], "en": ["I'll keep writing verse, it's true,", "bringing beauty to the people, too."], "day": "05-27", "occ_hr": "napisano na današnji dan, 2011.", "occ_en": "written on this day in 2011"}, {"slug": "sva-godisnja-doba", "title_hr": "Sva godišnja doba", "title_en": "All the Seasons", "hr": ["Kada sam te sreo uz mirisno cvijeće,", "zadrhtaše strune od osmijeha tvoga.", "Za mene je bilo zeleno proljeće.", "S tobom mi je sreća došla dana toga."], "en": ["When I met you where the fragrant flowers grew,", "at your smile the strings began to tremble so;", "for me it was the springtime, green and new;", "with you came happiness that day, I know."], "day": "05-28"}, {"slug": "podravino-diko-moja", "title_hr": "Podravino, diko moja", "title_en": "Podravina, My Pride", "hr": ["Još te volim, rodni kraju,", "meni treba ljubav tvoja.", "Eh, da mogu prošlost vratiti,", "Podravino, diko moja!"], "en": ["Still I love you, native land;", "and I need that love of thine.", "Ah, if I could bring the past back,", "Podravina, pride of mine!"], "day": "05-29"}, {"slug": "hrvatski-ponos", "title_hr": "Hrvatski ponos", "title_en": "Croatian Pride", "hr": ["Ja sam Hrvat, to morate znati,", "jer hrvatska rodila me mati", "i sa svojim mlijekom nadajala,", "u hrvatskom duhu odgajala."], "en": ["I am a Croat — this you ought to know,", "for a Croatian mother bore me so,", "and it was with her milk that I was fed,", "and in the Croatian spirit I was bred."], "day": "05-30", "occ_hr": "Dan državnosti", "occ_en": "Statehood Day"}, {"slug": "ljubav-se-ne-mjeri", "title_hr": "Ljubav se ne mjeri", "title_en": "Love Is Not Measured", "hr": ["Ne mogu ti reći koliko te volim,", "jer se ljubav, dušo, ne mjeri aršinom."], "en": ["I cannot tell you, darling, just how much I love you,", "for love is not a thing a yardstick can define."], "day": "05-31"}, {"slug": "ima-li-sto-ljepse-od-djeteta", "title_hr": "Ima li što ljepše od djeteta", "title_en": "Is There Anything Lovelier Than a Child", "hr": ["Ima li što ljepše od djeteta,", "tako nježnog, malenog stvora!?", "Kada kraj tebe nespretno puzi,", "kada ti guče umjesto govora."], "en": ["Is anything more lovely than a child,", "so delicate, so tiny a creation!?", "When clumsily it crawls there at your side,", "when it coos to you instead of conversation."], "day": "06-01", "occ_hr": "Međunarodni dan djeteta", "occ_en": "International Children's Day"}, {"slug": "ribar", "title_hr": "Ribar", "title_en": "The Fisherman", "hr": ["Dok se magla diže,", "topola se njiše.", "Dotle svaki ribar", "vel'ku ribu sniva."], "en": ["And while the mist is lifting,", "the poplar tree is swaying;", "and meanwhile every angler", "dreams of a great big fish."], "day": "06-02"}, {"slug": "rascvjetano-ljeto", "title_hr": "Rascvjetano ljeto", "title_en": "Summer in Full Bloom", "hr": ["Oko nas je rascvjetano ljeto.", "Sunce grije i nebo se plavi,", "a nas dvoje, dva malena cvijeta,", "ostali smo ležati u travi."], "en": ["All around us, summer was in bloom,", "warm the sun, the sky above so blue,", "and the two of us, two little flowers,", "lay on in the grass the whole day through."], "day": "06-03"}, {"slug": "stedisa", "title_hr": "Štediša", "title_en": "The Little Saver", "hr": ["„Veliki sladoled", "kupit ću sebi", "od deset kugli –", "pa zašto ne bih?"], "en": ["\"I'll buy myself an ice cream,", "a great big one, oh my,", "with ten scoops on it —", "and why shouldn't I?"], "day": "06-04"}, {"slug": "bara", "title_hr": "Bara", "title_en": "The Pond", "hr": ["Na njenom drveću", "ptičice ćurliču,", "djeca se u bari", "kupaju i viču."], "en": ["On its trees the birdies", "twitter all about;", "in the pond the children", "bathe and splash and shout."], "day": "06-05"}, {"slug": "podaci-o-pjesniku", "title_hr": "Podaci o pjesniku", "title_en": "Particulars of the Poet", "hr": ["Ja ne skrbim kruh u znoju,", "mirovinu imam svoju.", "I kućicu svoju imam,", "pa u noći divno snivam,", "preko dana u njoj dišem", "i tu svoje pjesme pišem."], "en": ["I no longer sweat for bread,", "I've my pension now instead.", "And my little house is mine,", "where at night I dream so fine;", "there by day I breathe and dwell,", "there I write my poems as well."], "day": "06-06"}, {"slug": "pjesma-valpovu", "title_hr": "Pjesma Valpovu", "title_en": "A Song to Valpovo", "hr": ["Tek u ljetu kad sunce zažeže,", "zlatnog klasja puna je dolina.", "Sve je ravno dokle oko seže,", "to bogatstvo gledat je milina."], "en": ["When the summer sun begins to blaze,", "golden ears fill all the valley plain;", "flat as far as ever eye can see —", "it's a joy to see such wealth of grain."], "day": "06-07"}, {"slug": "oglas-tete-lije", "title_hr": "Oglas Tete Lije", "title_en": "Auntie Fox's Notice", "hr": ["Noćas na ogradi", "ostao mi brk", "zbog jedne lude,", "pseće sile.", "Molim nalaznika", "da brk zadrži,", "a meni donese", "koku ili pile."], "en": ["Last night on a fence", "I lost a whisker,", "all thanks to a mad", "dog's brute force.", "I ask the finder", "to keep the whisker", "and bring me a hen", "or a chick, of course."], "day": "06-08"}, {"slug": "haiku", "title_hr": "Haiku", "title_en": "Haiku", "hr": ["OLUJA:", "Oblaci plaču,", "zvijezda vara mjeseca,", "gromovi ječe."], "en": ["Storm:", "The clouds are weeping,", "a star cheats on the moon,", "the thunders groan."], "day": "06-09"}, {"slug": "etno-kuca-zelcin", "title_hr": "Etno kuća Zelčin", "title_en": "The Ethno House at Zelčin", "hr": ["U dvorištu ambar prazan stoji,", "još se sjeća kad je bogat bio,", "sva su okna bila puna žita", "i miša je često pogostio."], "en": ["The granary stands empty in the yard;", "it still recalls when it was rich and fine,", "when all its bins were brimming full of grain,", "and often it would treat a mouse to dine."], "day": "06-10"}, {"slug": "dragutinu-gibicaru", "title_hr": "Dragutinu Gibičaru", "title_en": "To Dragutin Gibičar", "hr": ["I starački dovukli se dani,", "još nam srca ukrotila nije.", "Ja vjerujem naše prijateljstvo", "da će vjerno ostat kao prije."], "en": ["And now the days of age have dragged along,", "and still they have not tamed our hearts, you see;", "I do believe our friendship will remain", "as faithful as it always used to be."], "day": "06-11", "occ_hr": "napisano na današnji dan, 2010.", "occ_en": "written on this day in 2010"}, {"slug": "i-jos-se-pitam", "title_hr": "I još se pitam", "title_en": "And I Still Wonder", "hr": ["Kako na dnu mora", "kose travu", "i kako muzu", "morsku kravu?"], "en": ["How do they mow", "grass on the sea floor,", "and how do they milk", "the sea cow, what's more?"], "day": "06-12"}, {"slug": "plavi-se-jadran-talasa", "title_hr": "Plavi se Jadran talasa", "title_en": "The Blue Adriatic Sways", "hr": ["Tko devize sobom nosi,", "Jadranom se plavim kiti,", "a naš radnik u snovima,", "može more samo sniti."], "en": ["Those who carry foreign money", "deck themselves in Adriatic blue,", "while our worker, in his dreams,", "only dreams the sea — that's true."], "day": "06-13"}, {"slug": "hvala-gradu-valpovu", "title_hr": "Hvala gradu Valpovu", "title_en": "Thank You, Town of Valpovo", "hr": ["„Tu mi žive predci od davnina,", "u pitomom kraju meni dragom,", "u ljepoti slavonskih ravnina,", "u Valpovu u gradiću blagom.“"], "en": ["“Here since the olden days my forebears dwell,", "within a gentle land I hold so dear,", "amid the beauty of Slavonia's plains,", "in Valpovo, the kindly town, right here.”"], "day": "06-14", "occ_hr": "napisano na današnji dan, 2010.", "occ_en": "written on this day in 2010"}, {"slug": "pjesma-sinu", "title_hr": "Pjesma sinu!", "title_en": "A Poem for My Son!", "hr": ["Živio sam s tobom sretno svoju mladost.", "Spavao si, sine, na mojim rukama.", "U igri sa tobom dijelio sam radost.", "Za bol tvoju ja sam bio na mukama."], "en": ["I lived my youth with you in happiness.", "You slept, my son, cradled within my arms.", "In playing with you, I would share your joy;", "and when you were in pain, I was in torment."], "day": "06-15", "occ_hr": "napisano na današnji dan, 1974.", "occ_en": "written on this day in 1974"}, {"slug": "blago-meni-jer-me-majka-zeni", "title_hr": "Blago meni, jer me majka ženi", "title_en": "Lucky Me, My Mother's Marrying Me Off", "hr": ["Kao momak u Sopju sam bio,", "ljepših cura, ja nisam vidio.", "Preko dana žito sam vršio,", "a navečer curice ljubio."], "en": ["When I was just a lad in Sopje, see,", "no prettier girls were ever seen by me.", "By day I used to thresh the wheat, and then", "at night I'd kiss the girls, and kiss again."], "day": "06-16"}, {"slug": "sokica", "title_hr": "Šokica", "title_en": "Šokica", "hr": ["Na polju je kao heroina,", "kada srpom zlatno klasje žanje.", "U posijelu uz kap rujnog vina,", "svom je diki umiljato janje."], "en": ["In the field she's like a heroine", "when her sickle reaps the golden grain;", "at the sijelo, with a drop of ruby wine,", "to her darling she's a gentle lamb again."], "day": "06-17"}, {"slug": "slavonija", "title_hr": "Slavonija", "title_en": "Slavonia", "hr": ["Kad navečer sunce zađe,", "bezbroj zvijezda nebom sija.", "Nigdje nema ljepšeg kraja", "nego što je Slavonija."], "en": ["When the sun has set at evening,", "countless stars across the sky —", "nowhere is a land more lovely", "than our own Slavonia."], "day": "06-18"}, {"slug": "kukuruz-za-prodaju", "title_hr": "Kukuruz za prodaju", "title_en": "Maize for Sale", "hr": ["A praščići kada bi ga jeli,", "kao lopte bili bi debeli.", "Pa i guska kad bi ga probala,", "svoje perce za njega bi dala."], "en": ["And piglets, if they ate it, I'd be bound,", "would all grow fat as balls, and just as round.", "And if a goose should taste it, then, I swear,", "she'd give her feathers for it, then and there."], "day": "06-19"}, {"slug": "dva-pjesnika-iz-dva-sela", "title_hr": "Dva pjesnika iz dva sela", "title_en": "Two Poets from Two Villages", "hr": ["Što pišemo pjesme, knjige,", "to je našoj duši hrana."], "en": ["Writing poems, writing books,", "is our souls' own food, I'd say."], "day": "06-20", "occ_hr": "napisano na današnji dan, 2010.", "occ_en": "written on this day in 2010"}, {"slug": "slavonac-na-jadranu", "title_hr": "Slavonac na Jadranu", "title_en": "A Slavonian on the Adriatic", "hr": ["Poj sirena još odzvanja zrakom,", "more šumi, vjetar ga talasa,", "ljepše pjesme nisam nikad čuo,", "do šuštanja zrelog žitnog klasa."], "en": ["The sirens' song still echoes on the air,", "the sea is murmuring, stirred by the wind again;", "a lovelier song I never yet have heard", "than the rustle of the ripened ears of grain."], "day": "06-21"}, {"slug": "procvjetala-stara-lipa", "title_hr": "Procvjetala stara lipa", "title_en": "The Old Linden Is in Bloom", "hr": ["Procvjetala stara lipa", "u dvorištu naše kuće,", "braco, seka, baka, deka,", "brali su je, eto, jučer."], "en": ["The old linden tree's in bloom", "in the yard beside our house;", "brother, sister, Gran and Grandpa", "picked its flowers just yesterday."], "day": "06-22"}, {"slug": "postovani-roko", "title_hr": "Poštovani Roko!", "title_en": "Dear Roko!", "hr": ["Uto roda tiho sleti", "i sa kljunom zaklepeće,", "Odlučio žabac stari,", "da sastanke više neće."], "en": ["Then a stork flew softly down", "and it clattered with its beak;", "the old frog made up his mind:", "no more meetings would he seek."], "day": "06-23"}, {"slug": "kad-ivanje-u-sopju-osvane", "title_hr": "Kad Ivanje u Sopju osvane", "title_en": "When St John's Day Dawns in Sopje", "hr": ["Bruji žica i vrisne Šokica,", "preko Luke odjekne ravnica.", "Ej, Sopjani, cvjetalo vam cvijeće", "čekat ćemo Dravsko pramaljeće."], "en": ["The strings are humming and a Šokica cries,", "across the Luka the whole plain replies.", "Hey, Sopje folk, may all your flowers bloom!", "We'll wait for Drava Spring to come round soon."], "day": "06-24", "occ_hr": "Ivanje · napisano na današnji dan, 2012.", "occ_en": "St John's Eve · written on this day in 2012"}, {"slug": "diljem-slavonije", "title_hr": "Diljem Slavonije", "title_en": "All Across Slavonia", "hr": ["Eh što volim \"VALPOVAČKO LJETO\"!", "Kad se skupi Šokadija mlada,", "pa se kolo šorom zavijori,", "a pod šat'rom svakojaka slada."], "en": ["Eh, how I love the \"Valpovo Summer\", yes!", "When the young Šokadija gathers round,", "and the kolo whirls along the village lane,", "and under the tent all kinds of treats are found."], "day": "06-25", "occ_hr": "Valpovačko ljeto", "occ_en": "Valpovo Summer festival"}, {"slug": "dakovo-je-biser-slavonije", "title_hr": "Đakovo je biser Slavonije", "title_en": "Đakovo Is the Pearl of Slavonia", "hr": ["Ravnica te plodovima hrani,", "a bregovi natapaju vinom.", "Sretan onaj tko u tebi živi,", "tko se može zvati tvojim sinom."], "en": ["The plain feeds you with all the fruits it yields,", "the hills keep you well watered with their wine.", "How happy he who lives within your bounds,", "who can be counted as a son of thine."], "day": "06-26"}, {"slug": "macak", "title_hr": "Mačak", "title_en": "The Tomcat", "hr": ["Eh, da mogu mačak biti,", "makar i crn bio.", "Rado bih se mladoj ženi,", "ja u krilu svio."], "en": ["Ah, if I could be a tomcat,", "even if a black one, still,", "gladly in a young wife's lap", "I'd curl up, if she will."], "day": "06-27"}, {"slug": "nek-se-slavi-u-sopju-veselje", "title_hr": "Nek' se slavi u Sopju veselje", "title_en": "Let Sopje Celebrate and Make Merry", "hr": ["Sopjani se sa agrarom bave,", "rodne njive plodove im daju.", "Svu ljepotu u svom selu slave,", "zato žive u zemaljskom raju."], "en": ["The Sopje people farm the land they till,", "their fertile fields give fruit of every kind;", "they celebrate the beauty of their village,", "and so they live in paradise, you'll find."], "day": "06-28"}, {"slug": "slavonija", "title_hr": "Slavonija", "title_en": "Slavonia", "hr": ["Opet tamo na istoku", "srijemskom se ravnicom veže", "talasasto more žita,", "sve dokle ti oko seže."], "en": ["There again, off to the east,", "joining Srijem's level plain,", "far as ever eye can see", "rolls a billowing sea of grain."], "day": "06-29"}, {"slug": "zaspalo-mace", "title_hr": "Zaspalo mače", "title_en": "The Sleeping Kitten", "hr": ["I kad spava, motor radi,", "ona tiho prede.", "Oh, te mačke baš ne znaju", "gorivo da štede!"], "en": ["Even sleeping, motor running,", "purring soft and deep.", "Oh, these cats just never learn", "fuel isn't cheap!"], "day": "06-30"}, {"slug": "domovino-moja", "title_hr": "Domovino moja", "title_en": "My Homeland", "hr": ["Slavonijo, zemljo ponosita,", "malo ravna, malo bregovita,", "zlatnim klasjem ti si okićena", "i sa rujnim vinom zalivena."], "en": ["Slavonia, O proud land of my birth,", "part level and part hilly is your earth,", "adorned with golden ears of wheat so fine,", "and watered well with ruby-coloured wine."], "day": "07-01"}, {"slug": "rascvjetano-ljeto", "title_hr": "Rascvjetano ljeto", "title_en": "Summer in Full Bloom", "hr": ["Ljetno sunce osušilo rosu,", "što je bila trava umivena.", "Nas smo dvoje sretni, zagrljeni,", "igrali se na otkosu sijena."], "en": ["Summer sunshine dried away the dew", "that had washed the grass at break of day;", "we two, happy, in each other's arms,", "on the swath of new-mown hay would play."], "day": "07-02"}, {"slug": "beracica-cvijeca", "title_hr": "Beračica cvijeća", "title_en": "The Flower Gatherer", "hr": ["Širio se miris pokošenog sijena,", "a zeleno polje i oku je milo."], "en": ["The scent of new-mown hay was spreading on the air,", "the green field, too, was sweet for eyes to see."], "day": "07-03", "occ_hr": "napisano na današnji dan, 1977.", "occ_en": "written on this day in 1977"}, {"slug": "cvrcak", "title_hr": "Cvrčak", "title_en": "The Cricket", "hr": ["Cvrčak cvrči,", "violinu svira.", "On ne voli", "da ga netko dira.", "Čim ga takneš,", "prestane da svira."], "en": ["The cricket chirps,", "fiddling away.", "He doesn't like", "being touched, I'd say.", "Touch him once,", "and he'll cease to play."], "day": "07-04"}, {"slug": "plavi-se-jadran-talasa", "title_hr": "Plavi se Jadran talasa", "title_en": "The Blue Adriatic Sways", "hr": ["Ljetno sunce morem žeže.", "Hoteli su stalno puni,", "a na plaži dupe griju,", "samo stranci i tajkuni."], "en": ["Summer sun scorches the sea,", "the hotels have no empty rooms,", "and warming bums upon the beach", "are only foreigners and tycoons."], "day": "07-05", "occ_hr": "napisano na današnji dan, 1985.", "occ_en": "written on this day in 1985"}, {"slug": "zora-te-meni-u-zagrljaj-vraca", "title_hr": "Zora te meni u zagrljaj vraća", "title_en": "Dawn Brings You Back into My Arms", "hr": ["Mi se gubimo u oblaku sreće,", "noć mi je tada blažena i kraća,", "a zlatnim zracima veselu, sretnu,", "zora te meni u zagrljaj vraća."], "en": ["We lose ourselves within a cloud of joy,", "my night is blissful then, and flies apace,", "and, glad and happy, on its golden rays,", "the dawn brings you back into my embrace."], "day": "07-06", "occ_hr": "napisano na današnji dan, 1983.", "occ_en": "written on this day in 1983"}, {"slug": "nista-ne-prodajem-vec-samo-dajem", "title_hr": "Ništa ne prodajem, već samo dajem", "title_en": "I'm Not Selling, Only Giving", "hr": ["Tako su lijepi, slatki i mali,", "slični su majci, vrh repa im fali.", "Namršte se i ponekad laju,", "pseći jezik već pomalo znaju."], "en": ["They're pretty, sweet, and little, every one;", "they're like their mum — except the tail-tip's gone.", "They frown, and now and then they bark, and — say! —", "they know a bit of dog-speak, in their way."], "day": "07-07"}, {"slug": "postovanom-mirku-novoselicu", "title_hr": "Poštovanom Mirku Novoseliću", "title_en": "To the Esteemed Mirko Novoselić", "hr": ["Kada budu Muze htjele,", "prihvati se pera tada,", "pusti maštu među zvijezde", "i dobit ćeš novog rada."], "en": ["When the Muses so desire,", "take the pen in hand right then,", "let your fancy roam the stars,", "and you'll have new work again."], "day": "07-08", "occ_hr": "napisano na današnji dan, 2010.", "occ_en": "written on this day in 2010"}, {"slug": "gospodinu-josipu-granjasu", "title_hr": "Gospodinu Josipu Granjašu", "title_en": "To Mr Josip Granjaš", "hr": ["Priroda nam radost krasi,", "bez povratka Drava plovi,", "tu promjene nikad nema,", "u prošlost nas vrate snovi."], "en": ["Nature graces all our joy,", "Drava flows, and never turns;", "here there's never any change;", "in our dreams the past returns."], "day": "07-09"}, {"slug": "ja-i-moj-medas-josip", "title_hr": "Ja i moj međaš Josip", "title_en": "Me and My Neighbour Josip", "hr": ["U tom svemu ipak nešto smeta,", "sad brojimo časno višak ljeta.", "Nikada nam nije bilo bolje:", "u raj ćemo protiv svoje volje!"], "en": ["In all of this, though, one thing's in the way:", "we count, with honour, extra years today.", "It's never been so good for us — and oh,", "to paradise, against our will, we'll go!"], "day": "07-10", "occ_hr": "napisano na današnji dan, 2013.", "occ_en": "written on this day in 2013"}, {"slug": "prijatelji-slavnog-komla-grada", "title_hr": "Prijatelji slavnog Komla grada", "title_en": "Friends from the Famous Town of Komlo", "hr": ["Što je lijepo neka dugo traje,", "obostrano družili se često,", "svu ljepotu to druženje daje,", "bilo naše ili vaše mjesto."], "en": ["What's lovely, let it last for many a day;", "may we meet often, taking turns again;", "such friendship gives all beauty, in its way,", "be it your town or ours, it's all the same."], "day": "07-11"}, {"slug": "ispod-stare-lipe", "title_hr": "Ispod stare lipe", "title_en": "Beneath the Old Linden", "hr": ["Kad bi stara lipa", "ispričati znala,", "sve poljupce slatke", "koje si mi dala."], "en": ["If the old linden", "could tell, if it knew,", "of all the sweet kisses", "that I had from you."], "day": "07-12", "occ_hr": "napisano na današnji dan, 1974.", "occ_en": "written on this day in 1974"}, {"slug": "mravinjak", "title_hr": "Mravinjak", "title_en": "The Anthill", "hr": ["Kada spavat pođu", "- eh, kakve li sloge! -", "Svi zubiće peru", "i malene noge."], "en": ["When it's time for bed", "— how in step they go! —", "they all brush their little teeth", "and wash each tiny toe."], "day": "07-13"}, {"slug": "sto-si-skrivila-generacijo", "title_hr": "Što si skrivila generacijo?", "title_en": "Generation, What Was Your Crime?", "hr": ["Radio sam četrdeset ljeta,", "da postanem socijalna bijeda."], "en": ["I've worked for forty summers, just to be", "a welfare case, reduced to misery."], "day": "07-14"}, {"slug": "auto-snova-a-malena-lova", "title_hr": "Auto snova, a malena lova", "title_en": "A Dream Car for a Little Cash", "hr": ["Nije meni samo da se proda,", "već da drugi pješice ne hoda."], "en": ["It isn't just a sale I'm hoping for,", "but that some other man need walk no more."], "day": "07-15"}, {"slug": "crvenkapa", "title_hr": "Crvenkapa", "title_en": "Little Red Riding Hood", "hr": ["Stazom hita Crvenkapa,", "ljetno sunce šumom plovi.", "Cvijeće bere, sluša ptice", "i leptire male lovi."], "en": ["Red Riding Hood speeds down the path;", "summer sun floats through the trees.", "She picks flowers, hears the birds,", "chases butterflies with ease."], "day": "07-16"}, {"slug": "prija", "title_hr": "Prija", "title_en": "My Prija", "hr": ["Nakon druge, treće čaše,", "jezici se razvezaše."], "en": ["By the second glass, the third,", "tongues were loosened, word by word."], "day": "07-17", "occ_hr": "napisano na današnji dan, 1997.", "occ_en": "written on this day in 1997"}, {"slug": "poezijski-rad-kroz-zivot", "title_hr": "Poezijski rad kroz život", "title_en": "A Life's Work in Poetry", "hr": ["I starački došli dani,", "nema zdravlja kao prije,", "ali srce moje gordo,", "ukrotila starost nije."], "en": ["Now the days of age are here,", "and my health is not the same,", "but this proud heart of mine", "age has never learned to tame."], "day": "07-18", "occ_hr": "napisano na današnji dan, 2010.", "occ_en": "written on this day in 2010"}, {"slug": "sismis-ili-mis", "title_hr": "Šišmiš ili miš", "title_en": "Flittermouse or Mouse", "hr": ["Bio jedan šišmiš", "koji je izgubio šiš,", "pa je postao miš.", "Šišmiš", "minus", "šiš,", "jednako", "miš!"], "en": ["Once there was a flittermouse", "who went and lost his flitter,", "and so became a mouse.", "Flittermouse", "minus", "flitter", "equals", "mouse!"], "day": "07-19"}, {"slug": "da-spasimo-stare-obicaje", "title_hr": "Da spasimo stare običaje", "title_en": "Let Us Save the Old Customs", "hr": ["Nekada se kosom zrelo žito želo,", "sa srpom kupilo, u snoplje vezalo,", "u krstine slagalo i kući vozilo,", "potom vršalicom žito ovršilo."], "en": ["Once they would mow the ripened wheat with scythes,", "and gather it with sickles, bind the sheaves,", "stack them in shocks, and cart them home by wain,", "and then the thresher threshed out all the grain."], "day": "07-20", "occ_hr": "napisano na današnji dan, 2008.", "occ_en": "written on this day in 2008"}, {"slug": "slavonac-na-jadranu", "title_hr": "Slavonac na Jadranu", "title_en": "A Slavonian on the Adriatic", "hr": ["Skitao sam po Jadranu plavom,", "od Rovinja do čuvenog Splita,", "ali nigdje ja vidio nisam,", "ljepšeg mora do slavonskog žita."], "en": ["I've roamed the blue Adriatic up and down,", "from Rovinj all the way to famous Split,", "but nowhere have I ever chanced to meet", "a lovelier sea than our Slavonian wheat."], "day": "07-21"}, {"slug": "puzic-i-kucica", "title_hr": "Pužić i kućica", "title_en": "The Little Snail and His House", "hr": ["Pitale ga gliste", "što se tako vuče:", "\"Mogu kako hoću,", "kod svoje sam kuće!\""], "en": ["The earthworms asked him why", "he dragged it all about:", "\"I can do as I please —", "this is my own house!\""], "day": "07-22"}, {"slug": "vatre-na-konjari", "title_hr": "Vatre na konjari", "title_en": "Fires on the Horse Pasture", "hr": ["Da je sve u redu vodili su pažnju", "i slaninu noću pekli su na ražnju.", "Da bi snove snili i veseli bili,", "Rakiju bi često iz čuture pili."], "en": ["They took good care that everything went right,", "and roasted bacon on the spit at night.", "To dream their dreams and keep a cheerful mind,", "they'd often drink rakija from the flask, you'll find."], "day": "07-23", "occ_hr": "napisano na današnji dan, 2011.", "occ_en": "written on this day in 2011"}, {"slug": "zov-domovine", "title_hr": "Zov domovine", "title_en": "The Call of the Homeland", "hr": ["Zato svoju zemlju i ljubi i voli,", "najdražom je zovi, vrijeđat ne dozvoli.", "Ona ti sve prašta, k'o rođena mati.", "Tu rođenu grudu treba čuvat znati."], "en": ["So love your land, and cherish her, and hold her dear;", "call her the dearest, let no insult come near.", "She forgives all, just like the mother of your birth;", "you must know how to keep and guard your native earth."], "day": "07-24"}, {"slug": "hodi-mjesece-zvijezdama", "title_hr": "Hodi, mjeseče, zvijezdama", "title_en": "Walk, O Moon, Among the Stars", "hr": ["Molim te, mjeseče sjajni,", "ne svijetli ove noći,", "kad poljubim dragu moju,", "ti možeš opet doći."], "en": ["Shining moon, I beg you, please,", "do not shine for us tonight;", "when I've kissed my darling, then", "you may come back into sight."], "day": "07-25", "occ_hr": "napisano na današnji dan, 1989.", "occ_en": "written on this day in 1989"}, {"slug": "zasto-covjek-nije-kao-dijete", "title_hr": "Zašto čovjek nije kao dijete", "title_en": "Why Is Man Not Like a Child", "hr": ["Zašto čovjek nije kao dijete", "što ne gleda porijeklo ni rasu", "Zašto mnogi kad odrastu", "među ljudstvom prave klasu?"], "en": ["Why is man not like a child", "that sees neither birth nor race?", "Why do many, once they're grown,", "split mankind by class and caste?"], "day": "07-26"}, {"slug": "dobro-dosli-prijatelji-dragi", "title_hr": "Dobro došli prijatelji dragi!", "title_en": "Welcome, My Dear Friends!", "hr": ["To je bilo trideset i treće,", "u mjesecu kad se žito želo,", "dvajs'devetog, a bio je petak,", "pa sam svakoj radosti početak."], "en": ["It was the year of nineteen thirty-three,", "the month when all the wheat was being reaped,", "the twenty-ninth, and Friday was the day,", "so I'm the start of every joy, I'd say."], "day": "07-27", "occ_hr": "napisano na današnji dan, 2012.", "occ_en": "written on this day in 2012"}, {"slug": "na-dan-vjencanja", "title_hr": "Na dan vjenčanja!", "title_en": "On Your Wedding Day!", "hr": ["U ovome času ti ćeš gnijezdo sviti.", "Uskoro ćeš i ti svoje čedo zvati.", "Voli svoje bližnje i voljen ćeš biti."], "en": ["This is the hour in which you'll build your nest;", "soon you as well will call a child your own.", "Love those close to you, and you'll be loved no less."], "day": "07-28", "occ_hr": "napisano na današnji dan, 1979.", "occ_en": "written on this day in 1979"}, {"slug": "poezijski-rad-kroz-zivot", "title_hr": "Poezijski rad kroz život", "title_en": "A Life's Work in Poetry", "hr": ["Ivan Benak mi je ime,", "pjesnik koji piše rime.", "Još od mojih školskih dana,", "poezija mi je hrana."], "en": ["Ivan Benak — that is me,", "poet writing rhymes, you see.", "Since my days at school began,", "poetry has fed this man."], "day": "07-29", "occ_hr": "Pjesnikov rođendan (1933.)", "occ_en": "The poet's birthday (1933)"}, {"slug": "san-o-sreci", "title_hr": "San o sreći", "title_en": "A Dream of Happiness", "hr": ["Da bi moje noge bose", "tresle hladnu rosu s trave,", "oko suzom zamagljeno,", "gledalo gdje pasu krave."], "en": ["So that my bare feet would shake", "the cold dew from the grass at dawn,", "and my eye, all dimmed with tears,", "watch the cows as they grazed on."], "day": "07-30"}, {"slug": "ne-sudi", "title_hr": "Ne sudi", "title_en": "Don't Judge", "hr": ["Tijelo mi je grubo,", "gipko kao Drava,", "jer ja sam rođen", "u znaku lava."], "en": ["My body is rough,", "lithe as the Drava's flow,", "for I was born", "in the sign of Leo."], "day": "07-31"}, {"slug": "suncokret-i-mak", "title_hr": "Suncokret i mak", "title_en": "The Sunflower and the Poppy", "hr": ["Na vrhu mu žuto tjeme,", "u glavi mu silno sjeme,", "klonu glava, teška, žuta,", "pade sjeme pokraj puta.", "Misli tužno suncokret:", "oh, što nisam crven cvijet?"], "en": ["On his top a yellow crown,", "in his head, seeds weighing down;", "heavy, yellow, droops his head,", "by the roadside seed is shed.", "Then the sunflower sadly said", "to himself: why am I not red?"], "day": "08-01"}, {"slug": "anice", "title_hr": "Anice", "title_en": "To Anica", "hr": ["Svakog dana kad zora zarudi,", "sretnu, vedru, nek' te sunce budi."], "en": ["Each day, as dawn is reddening the skies,", "may the sun wake you glad and bright to rise."], "day": "08-02"}, {"slug": "poezija-na-trznici", "title_hr": "Poezija na tržnici", "title_en": "Poetry at the Market", "hr": ["Kolovozom svakog ljeta,", "pjesnici se gordo roje,", "u Đakovu, na tržnici,", "čitajući pjesme svoje."], "en": ["In the August of each year,", "poets proudly swarm, each one,", "in Đakovo, at the market,", "reading poems of their own."], "day": "08-03", "occ_hr": "napisano na današnji dan, 2009.", "occ_en": "written on this day in 2009"}, {"slug": "uslisi-me-boze", "title_hr": "Usliši me, Bože", "title_en": "Hear Me, O God", "hr": ["Hoću li, Bože, i ja u raj?", "To iskreno želim, ali se bojim.", "U raju će biti slava i sjaj,", "a ja Ti na lošem glasu stojim."], "en": ["Shall I too, O God, to heaven go?", "I truly wish it, yet I live in fear.", "In heaven there'll be glory, splendour's glow,", "and my good name with You is poor down here."], "day": "08-04"}, {"slug": "rodena-gruda", "title_hr": "Rođena gruda", "title_en": "Native Soil", "hr": ["Najljepše je uvijek na rođenoj grudi", "i zemljica ova što te kruhom hrani.", "Tu si se rodio, tu živi i budi.", "Ne daj domovinu, s ljubavlju je brani."], "en": ["The loveliest place is always one's own native ground,", "and this dear little earth that feeds you with its bread.", "Here you were born; here live, and here be found.", "Don't give your homeland up; with love, defend her well."], "day": "08-05", "occ_hr": "Dan pobjede i domovinske zahvalnosti", "occ_en": "Victory and Homeland Thanksgiving Day"}, {"slug": "unuci-andreji-2", "title_hr": "Unuci Andreji", "title_en": "To My Granddaughter Andreja", "hr": ["Svu hranu voli rado da jede,", "to je od svoga vidjela djede."], "en": ["She gladly eats all kinds of food, every bite —", "she's learned that from watching her grandpa, all right!"], "day": "08-06"}, {"slug": "lastina-kuca", "title_hr": "Lastina kuća", "title_en": "The Swallow's House", "hr": ["Maleni brzo rastu,", "dođe i konac ljeta.", "U jata se tada skupe –", "odoše na kraj svijeta!"], "en": ["The little ones grow quickly,", "and summer's end draws nigh;", "then into flocks they gather —", "off to the world's end they fly!"], "day": "08-07"}, {"slug": "hrabra-budi", "title_hr": "Hrabra budi", "title_en": "Be Brave", "hr": ["Kada mora iz snova te budi,", "kada tuga razara ti grudi,", "kada netko zbog ljubavi sudi,", "ti ne plači, nego hrabra budi."], "en": ["When a nightmare wakes you from your sleep,", "when your breast is torn by sorrow deep,", "when someone condemns you for your love,", "then be brave, my darling, do not weep."], "day": "08-08", "occ_hr": "napisano na današnji dan, 1987.", "occ_en": "written on this day in 1987"}, {"slug": "ugodno-druzenje-umirovljenika", "title_hr": "Ugodno druženje umirovljenika", "title_en": "A Pleasant Pensioners' Get-Together", "hr": ["Veselo je, hvala dragom Bogu,", "zaigraše kolo, tango, polku,", "nek se vidi što PENZIĆI mogu,", "sutra ćemo misliti na boljku."], "en": ["It's merry, thanks be to the Lord above;", "they danced the kolo, tango, polka too;", "let all now see what oldies still can do —", "tomorrow we'll give aches a thought or two."], "day": "08-09"}, {"slug": "hvaljen-isus-majko-nasa", "title_hr": "Hvaljen Isus, Majko naša", "title_en": "Praised Be Jesus, Our Mother", "hr": ["Mnogi ljudi na svetištu,", "svetoj Gospi zavjet daju.", "Da l' zbog bola ili jada,", "kakav problem već imaju."], "en": ["Many people at the shrine", "make the holy Lady a vow,", "be it out of pain or sorrow,", "or what troubles they have now."], "day": "08-10", "occ_hr": "napisano na današnji dan, 2010.", "occ_en": "written on this day in 2010"}, {"slug": "ribar", "title_hr": "Ribar", "title_en": "The Fisherman", "hr": ["Sve je svoje brige", "bacio u vodu,", "a niti ga muči", "kad će doći kući."], "en": ["Every care he had", "he's tossed into the drink,", "nor does he give a thought", "to when he'll get back home."], "day": "08-11"}, {"slug": "opijelo-ljubavi", "title_hr": "Opijelo ljubavi", "title_en": "Requiem for Love", "hr": ["Zašto uvijek pišem na kraju života?", "A preskačem sreću onih prvih dana,", "dok još srce nije bilo puno rana?"], "en": ["Why do I always write when life is at its end,", "and skip the happiness of those first days, the start,", "when wounds had not yet filled up all my heart?"], "day": "08-12"}, {"slug": "umirovljenicki-jadi", "title_hr": "Umirovljenički jadi", "title_en": "A Pensioner's Woes", "hr": ["Kad pogledam što u kasi osta,", "taman, brale, za rakiju dosta.", "Da popijem i ublažim tugu", "čekajući crkavicu drugu."], "en": ["And when I see what's left inside my till,", "there's just enough, old mate, for rakija still,", "to drink it down and ease my grief a bit,", "and wait for the next pittance after it."], "day": "08-13"}, {"slug": "zora-te-meni-u-zagrljaj-vraca", "title_hr": "Zora te meni u zagrljaj vraća", "title_en": "Dawn Brings You Back into My Arms", "hr": ["U mislima s tobom, zorom se budim,", "kada se zlatno sunašce rađa.", "U grudima, draga, svuda te nosim.", "Od ljubavnog žara postaješ mlađa."], "en": ["In thoughts with you, I wake up with the dawn,", "as the small golden sun is being born;", "I carry you, my darling, in my breast —", "love's ardour makes you younger every morn."], "day": "08-14"}, {"slug": "bol-kroz-zivot", "title_hr": "Bol kroz život", "title_en": "A Lifetime of Pain", "hr": ["Ponekad se teško hodi,", "neravni su često puti,", "kroz život me sudba vodi.", "Ti uz mene, Gospo, budi!"], "en": ["Sometimes it is hard to walk,", "often rugged is the way;", "fate is leading me through life.", "Lady, stay by me, I pray!"], "day": "08-15", "occ_hr": "Velika Gospa", "occ_en": "Assumption Day"}, {"slug": "storija-o-mati-i-kati", "title_hr": "Storija o Mati i Kati", "title_en": "The Story of Mata and Kata", "hr": ["Al' samoća dušu truje,", "mladost traži želje svoje,", "a noći su puste, duge,", "ljepši život je u dvoje."], "en": ["Loneliness will poison souls,", "youth has longings of its own,", "and the nights are long and empty:", "life is sweeter not alone."], "day": "08-16", "occ_hr": "napisano na današnji dan, 2004.", "occ_en": "written on this day in 2004"}, {"slug": "izgubljena-cipelica", "title_hr": "Izgubljena cipelica", "title_en": "The Lost Shoe", "hr": ["Izgubih svoju", "cipelu desnu,", "ali ja ne znam", "s noge koje.", "Molim nalaznika", "da sam provjeri,", "jer stonoge svoje", "noge ne broje."], "en": ["I've lost my shoe,", "my right one, oh,", "but from which foot", "I just don't know.", "Will the finder please", "check it for me, do?", "For centipedes never", "count their feet, it's true."], "day": "08-17"}, {"slug": "pjesma-valpovu", "title_hr": "Pjesma Valpovu", "title_en": "A Song to Valpovo", "hr": ["Kad u parku ptice zapjevaju,", "nigdje nema tako lijepog kraja.", "Rodne njive plodove nam daju,", "to je dio zemaljskoga raja."], "en": ["When the birds begin to sing in the park,", "nowhere is a land as fair as this;", "fertile fields give us their fruit in plenty —", "it's a part of earthly paradise."], "day": "08-18"}, {"slug": "etno-kuca-zelcin", "title_hr": "Etno kuća Zelčin", "title_en": "The Ethno House at Zelčin", "hr": ["Pod orahom djeda kosu kuje,", "baka užad plete pokraj kuće.", "Miris kruha dvorištem se širi,", "bit će danas i pogače vruće."], "en": ["Beneath the walnut Grandpa peens his scythe,", "and Grandma plaits her ropes beside the wall;", "the smell of bread is spreading through the yard,", "today there'll be hot flatbread for us all."], "day": "08-19", "occ_hr": "napisano na današnji dan, 2006.", "occ_en": "written on this day in 2006"}, {"slug": "ljubav-se-ne-mjeri", "title_hr": "Ljubav se ne mjeri", "title_en": "Love Is Not Measured", "hr": ["Nikad neću žalit' što sam te ljubio.", "Za tvoju sam ljubav tebi svoju dao.", "Da se opet rodim, opet bih tvoj bio", "i na grudi tvoje sav sretan bih pao."], "en": ["I'll never feel regret that I have loved you, loved you so.", "For all your love I gave you mine, and held back none at all.", "And were I born again, I'd be yours once again, I know,", "and on your breast, in perfect happiness, I'd fall."], "day": "08-20"}, {"slug": "prodah-motor-kaciga-ostala", "title_hr": "Prodah motor, kaciga ostala", "title_en": "I Sold the Motorbike, the Helmet Stayed", "hr": ["Kada padaš, i ugledaš zvijezdu,", "siguran si, kao ptić u gnijezdu."], "en": ["And when you fall and see a star or two,", "you're safe as a chick in its nest — it's true."], "day": "08-21", "occ_hr": "napisano na današnji dan, 2004.", "occ_en": "written on this day in 2004"}, {"slug": "haiku", "title_hr": "Haiku", "title_en": "Haiku", "hr": ["SVITANJE:", "Mjesec se gasi,", "pijetao kljuca zoru,", "miriše jutro."], "en": ["Dawn:", "The moon is going out,", "a rooster pecks at the dawn,", "the morning's fragrant."], "day": "08-22"}, {"slug": "postovani-josipe", "title_hr": "Poštovani Josipe!", "title_en": "Dear Josip!", "hr": ["Život bez povratka", "polako teče,", "po stazama trnje", "tek poneko cvijeće."], "en": ["Life that won't return", "slowly flows along;", "thorns upon the pathways,", "and few flowers among."], "day": "08-23", "occ_hr": "napisano na današnji dan, 2010.", "occ_en": "written on this day in 2010"}, {"slug": "kad-tambura-srce-dira", "title_hr": "Kad tambura srce dira", "title_en": "When the Tambura Touches the Heart", "hr": ["Sviraj samo, prijatelju,", "novu glazbu svakog dana,", "pa će tvojim časnim radom,", "Valpovština biti znana!"], "en": ["Just keep playing, my good friend,", "some new music every day,", "so your honest work will make", "Valpovština known far away!"], "day": "08-24", "occ_hr": "napisano na današnji dan, 2013.", "occ_en": "written on this day in 2013"}, {"slug": "0-5-promila", "title_hr": "0.5 promila", "title_en": "0.5 Per Mille", "hr": ["Radi naših mladenaca,", "da bi svadba lijepa bila,", "vratite nam stari zakon,", "bar na nula-pet promila!"], "en": ["For the sake of our young couples,", "so each wedding's lovely still,", "give us back the law we had —", "at least zero point five per mille!"], "day": "08-25", "occ_hr": "napisano na današnji dan, 2004.", "occ_en": "written on this day in 2004"}, {"slug": "suha-kora-prove", "title_hr": "Suha kora prove", "title_en": "The Dry Crust of Cornbread", "hr": ["U snovima bijelog kruha,", "svježu krišku ja sam snio,", "a na javi koru prove", "suzama sam natopio."], "en": ["In my dreams I used to dream", "of a fresh white slice of bread,", "but awake, the cornbread crust", "I would soak with tears instead."], "day": "08-26"}, {"slug": "kako-nosorog-brise-nos", "title_hr": "Kako nosorog briše nos", "title_en": "How the Rhino Wipes His Nose", "hr": ["Kako nosorog", "briše nos", "kada na njemu", "ima rog?"], "en": ["How does a rhino", "wipe his nose", "when a horn", "right on it grows?"], "day": "08-27"}, {"slug": "nard-je-selo-sto-ga-ljubi-drava", "title_hr": "Nard je selo što ga ljubi Drava", "title_en": "Nard Is the Village the Drava Kisses", "hr": ["Na tamburi kada cikne žica,", "odjekuje Slavonska ravnica."], "en": ["When on the tambura a string rings high,", "the plain of Slavonia echoes in reply."], "day": "08-28"}, {"slug": "podravino-diko-moja", "title_hr": "Podravino, diko moja", "title_en": "Podravina, My Pride", "hr": ["Ja u Sopju nikog nemam,", "al' me srce k njemu vuče.", "Ostalo mi tu djetinjstvo", "u sjećanju stare kuće."], "en": ["I have no one now in Sopje,", "yet my heart is drawn there, too;", "there my childhood stayed behind,", "in the old house that I knew."], "day": "08-29", "occ_hr": "napisano na današnji dan, 2011.", "occ_en": "written on this day in 2011"}, {"slug": "u-povjerenju", "title_hr": "U povjerenju", "title_en": "In Confidence", "hr": ["Mladost bješe kratka", "na ovome svijetu.", "Zato ljubljah žene", "u najljepšem cvijetu."], "en": ["Youth was all too brief", "in this world of ours;", "so I kissed the women", "in their fairest flower."], "day": "08-30"}, {"slug": "dragi-prijatelji", "title_hr": "Dragi prijatelji!", "title_en": "Dear Friends!", "hr": ["Želim da kroz knjigu ovu,", "naše prijateljstvo traje,", "jer stihovi ove knjige", "daju nježne osjećaje."], "en": ["It's my wish that through this book", "may our friendship last and stay,", "for the verses in this book", "tender feelings do convey."], "day": "08-31"}, {"slug": "tatina-lutkica", "title_hr": "Tatina lutkica", "title_en": "Daddy's Little Doll", "hr": ["Imam jednu lutkicu,", "jedno malo đače,", "pa od škole do kuće", "cupka kao pače."], "en": ["I have a little dolly,", "a little schoolgirl, who", "comes hopping home from school", "the way that ducklings do."], "day": "09-01"}, {"slug": "lastavica", "title_hr": "Lastavica", "title_en": "The Swallow", "hr": ["Išao bih s tobom", "u tople krajeve,", "ali krila nemam", "da letim po svijetu."], "en": ["I would go with you", "to the lands where it's warm,", "but I have no wings", "to fly the whole world through."], "day": "09-02"}, {"slug": "cuvarima-noci", "title_hr": "Čuvarima noći", "title_en": "To the Guardians of the Night", "hr": ["Ništa ljepše od tambure nema,", "pogotovo kad se svadba sprema."], "en": ["There's nothing lovelier than the tambura's play,", "especially when a wedding's on the way."], "day": "09-03"}, {"slug": "kritika", "title_hr": "Kritika", "title_en": "Criticism", "hr": ["Meni kad želje se jave,", "k'o jesenje guste kiše,", "u ruci pero se nađe", "i samo pjesme piše."], "en": ["But when my longings gather", "like autumn's heavy rain,", "a pen turns up in my hand", "and writes poems once again."], "day": "09-04"}, {"slug": "skolska-torba", "title_hr": "Školska torba", "title_en": "The School Bag", "hr": ["Nije teška, vjerujte,", "svi je đaci nose,", "a znanja je prepuna", "kao cvijeće rose."], "en": ["It's not heavy, honestly,", "every pupil bears it, too,", "and it's brimming full of knowledge", "as the flowers are with dew."], "day": "09-05", "occ_hr": "Početak škole", "occ_en": "First day of school"}, {"slug": "nek-se-slavi-u-sopju-veselje", "title_hr": "Nek' se slavi u Sopju veselje", "title_en": "Let Sopje Celebrate and Make Merry", "hr": ["Sve dok bude bilo Slavonije,", "skupljat će se Šokadija naša", "i veselja bit će kao prije,", "uz tambure dobrih tamburaša."], "en": ["As long as there's Slavonia on the earth,", "our Šokadija will come together still,", "and there'll be merriment as once there was,", "as good tambura players show their skill."], "day": "09-06", "occ_hr": "napisano na današnji dan, 2012.", "occ_en": "written on this day in 2012"}, {"slug": "buduci-nogometas", "title_hr": "Budući nogometaš", "title_en": "The Future Footballer", "hr": ["U mislima svojim", "još golove niže,", "nikakve zadatke", "ne može da piše."], "en": ["In his thoughts he's still", "scoring goal on goal;", "not a single sum", "can he write at all."], "day": "09-07"}, {"slug": "destinacije-opcine-sopja", "title_hr": "Destinacije općine Sopja", "title_en": "Destinations of Sopje Municipality", "hr": ["Ritska Ada tu je nekad bila,", "pjesnika je ona iznjedrila.", "Još je ovdje, samo što se skriva,", "pjesnikovo još djetinjstvo sniva."], "en": ["Here, long ago, was Ritska Ada's place;", "it brought the poet forth from its embrace.", "It's still here, only hiding from our view,", "and still the poet's childhood dreams there, too."], "day": "09-08", "occ_hr": "napisano na današnji dan, 2011.", "occ_en": "written on this day in 2011"}, {"slug": "dobio-sam-pjesmu-od-marice", "title_hr": "Dobio sam pjesmu od Marice", "title_en": "I've Had a Poem from Marica", "hr": ["Poznato je, žene puno rade,", "u proljeće razno bilje sade.", "Dođe jesen, priroda se zlati,", "žena opet za zimnicu radi."], "en": ["It's common knowledge: women work a lot;", "in spring they plant all kinds in every plot.", "Then autumn comes, and nature turns to gold,", "and wives again put stores up for the cold."], "day": "09-09"}, {"slug": "nudim-kazan-sto-rakiju-pece", "title_hr": "Nudim kazan što rakiju peče", "title_en": "A Rakija Still for Sale", "hr": ["Prodah salaš i voljenu njivu,", "sa njom voćnjak i valpovku šljivu.", "Sad mi kazan u pecari spava,", "prod'o bih ga, istina je prava."], "en": ["I sold my farmstead and the field I prized,", "the orchard and the Valpovka plums likewise.", "My still now sleeps inside the still-house, so", "I'd sell it — that's the honest truth, you know."], "day": "09-10", "occ_hr": "napisano na današnji dan, 2000.", "occ_en": "written on this day in 2000"}, {"slug": "neposlusni-vrabac", "title_hr": "Neposlušni vrabac", "title_en": "The Disobedient Sparrow", "hr": ["Neka vam ovo, djeco,", "bude savjet mali:", "Uvijek slušajte starije,", "da biste što više znali!"], "en": ["Let this be, dear children,", "a small piece of advice:", "always listen to your elders,", "and you will grow up wise!"], "day": "09-11"}, {"slug": "cestitka", "title_hr": "Čestitka", "title_en": "A Greeting", "hr": ["Daleko sam od tebe,", "ali sam s tobom.", "Misli moje k tebi hrle."], "en": ["I am far away from you,", "and yet I'm with you.", "My thoughts to you come pressing."], "day": "09-12", "occ_hr": "napisano na današnji dan, 1997.", "occ_en": "written on this day in 1997"}, {"slug": "lastavica", "title_hr": "Lastavica", "title_en": "The Swallow", "hr": ["Kada dođe jesen,", "srce me zazebe.", "S odlaskom svojim", "stvaraš meni sjetu."], "en": ["When the autumn comes,", "my heart feels a chill;", "as you fly away,", "you leave me sad and blue."], "day": "09-13"}, {"slug": "dva-bureta-prodajem-za-vino", "title_hr": "Dva bureta prodajem za vino", "title_en": "Two Wine Barrels for Sale", "hr": ["Kad u jesen napunim bačvicu,", "svakog dana uzimam litricu.", "Godinama ja već tako radim,", "pijem vino, pomalo se sladim."], "en": ["When in the autumn I have filled the cask,", "a litre every day is all I ask.", "For years and years I've done it just this way:", "I drink my wine and savour it each day."], "day": "09-14"}, {"slug": "dolazak-zime", "title_hr": "Dolazak zime", "title_en": "The Coming of Winter", "hr": ["Berači zrele plodove beru", "i poljem pjevaju glasno.", "Uskoro, djeco, doći će zima,", "to nam je sada jasno."], "en": ["The pickers gather in the ripened fruit", "and through the fields sing loud and clear.", "Soon, children, winter's coming; now", "we see it plainly: it is near."], "day": "09-15"}, {"slug": "radio-burza", "title_hr": "Radio burza", "title_en": "Radio Burza", "hr": ["Dok jutarnju svoju kavu pijem,", "slušam burzu, pa se i nasmijem.", "To je program što se rado sluša,", "svega ima što ti želi duša."], "en": ["While sipping at my morning coffee cup,", "I hear the Burza, and it cheers me up.", "It is a programme people love to hear:", "whatever your soul wishes, it is here."], "day": "09-16", "occ_hr": "napisano na današnji dan, 2000.", "occ_en": "written on this day in 2000"}, {"slug": "skolska-torba", "title_hr": "Školska torba", "title_en": "The School Bag", "hr": ["S odličnim bi uspjehom", "prošla škola svaka,", "kad bi torba odgovor", "dala mjesto đaka."], "en": ["Every school would pass with honours,", "every single one,", "if the school bag gave the answers", "and the pupils none."], "day": "09-17"}, {"slug": "sopju-s-ljubavlju", "title_hr": "Sopju s ljubavlju", "title_en": "To Sopje, With Love", "hr": ["Podravino, mili zavičaju,", "selo Sopje u tebi se svilo.", "Nema ljepšeg od tvojega kraja,", "uvijek mi je tu najbolje bilo."], "en": ["Podravina, my dear native land,", "the village Sopje nestles in your breast;", "there's nothing lovelier than your countryside,", "and here is where I've always felt the best."], "day": "09-18", "occ_hr": "napisano na današnji dan, 2012.", "occ_en": "written on this day in 2012"}, {"slug": "0-5-promila", "title_hr": "0.5 promila", "title_en": "0.5 Per Mille", "hr": ["Ujesen se svadbe prave", "uz obilje rujnog vina.", "Svaki otac raduje se,", "kada ženi svoga sina."], "en": ["Autumn's when the weddings come,", "with red wine in rich supply;", "every father's heart is glad", "when he marries off his son."], "day": "09-19"}, {"slug": "imam-jedno-djevojce", "title_hr": "Imam jedno djevojče", "title_en": "I Have a Little Sweetheart", "hr": ["A kada je ne vidim,", "tužan mi je svijet", "jer bez njenog poljupca", "ne miriše cvijet."], "en": ["And when I cannot see her,", "the world's a sad affair,", "for, lacking her sweet kisses,", "no flower scents the air."], "day": "09-20", "occ_hr": "napisano na današnji dan, 1974.", "occ_en": "written on this day in 1974"}, {"slug": "tatina-lutkica", "title_hr": "Tatina lutkica", "title_en": "Daddy's Little Doll", "hr": ["Oh, pomozi, tatice!", "Tko da povijest znade!?", "Pa mi učiteljica", "jedinicu dade."], "en": ["Oh, help me, Daddy, help!", "Who can know history?!", "And so my teacher went", "and gave an F to me."], "day": "09-21"}, {"slug": "suzani-za-rodendan", "title_hr": "Suzani za rođendan", "title_en": "For Suzana's Birthday", "hr": ["Za tren oka nestalo djetinjstvo,", "u nepovrat otišli su snovi.", "Kćeri mila, od srca ti želim,", "da ti budu sretni dani novi."], "en": ["Your childhood vanished in the blink of an eye,", "your dreams have gone away, not to return.", "My darling daughter, from my heart I wish", "that happy new days now be yours in turn."], "day": "09-22"}, {"slug": "hvala-ti-draga", "title_hr": "Hvala ti, draga!", "title_en": "Thank You, Darling!", "hr": ["Još su oči tvoje, mila, pune čežnje,", "a riječi su tople, iskrene i nježne.", "Oh, ljubavi moja, na svemu ti hvala."], "en": ["Still full of longing are your eyes, my dear,", "and your words are warm and tender and sincere.", "Oh, my love, for everything, my thanks to you."], "day": "09-23", "occ_hr": "napisano na današnji dan, 1973.", "occ_en": "written on this day in 1973"}, {"slug": "dobio-sam-pjesmu-od-marice", "title_hr": "Dobio sam pjesmu od Marice", "title_en": "I've Had a Poem from Marica", "hr": ["I sad gledam kako šljive zriju,", "čekam vrijeme da pečem rakiju."], "en": ["And now I watch the plums grow ripe, until", "it's time to make rakija in the still."], "day": "09-24"}, {"slug": "radosno-djetinjstvo", "title_hr": "Radosno djetinjstvo", "title_en": "Happy Childhood", "hr": ["Igraju se i pjevaju,", "tu na djecu tete paze,", "djeci pjesme tu čitaju", "i tete ih divno maze.", "U igri im nema kraja,", "to je dio pravog raja."], "en": ["Here they play and here they sing,", "and the aunties mind them there;", "here they read the children rhymes,", "and they cuddle them with care.", "There's no end to all their play,", "it's a piece of heaven, I'd say."], "day": "09-25"}, {"slug": "oj-oraje-oraje", "title_hr": "Oj, oraje, oraje", "title_en": "Oh, Walnut, Walnut Tree", "hr": ["Orah dobro rodi", "ima jezgru pravu,", "ali baba veli:", "ne za sijedu glavu."], "en": ["The walnut tree bears well,", "good kernels, I'd say,", "but granny says: \"Not meant", "for a head that's grey.\""], "day": "09-26"}, {"slug": "majka", "title_hr": "Majka", "title_en": "Mother", "hr": ["Kad čuje bilo srca njenog,", "toplinu osjeti majke,", "ona je njemu božica sreće,", "ljepša od svake bajke."], "en": ["When it hears her heart's soft beating", "and it feels its mother's warmth,", "she's its goddess of all gladness,", "lovelier than any fairy tale."], "day": "09-27"}, {"slug": "stiglo-nam-i-vincekovo", "title_hr": "Stiglo nam i Vincekovo", "title_en": "Now St Vincent's Day Has Come", "hr": ["I to vinsko trebat će nam blago,", "kad ostvare mladi svoje snove.", "Dođe jesen i vino poteče,", "slavit ćemo veselo svatove."], "en": ["And we'll need that wealth of wine, that treasure,", "when the young ones make their dreams come true.", "Autumn comes, and wine begins to flow:", "gladly we will feast the wedding through."], "day": "09-28"}, {"slug": "dolazak-zime", "title_hr": "Dolazak zime", "title_en": "The Coming of Winter", "hr": ["Jesenje kiše tjeraju ljeto,", "lišće polako žuti.", "Po cesti vjetar prašinu diže", "i huči – valjda se ljuti."], "en": ["The autumn rains are driving summer out,", "the leaves are slowly turning yellow.", "Along the road the wind whips up the dust", "and howls: perhaps he's cross, the fellow."], "day": "09-29", "occ_hr": "Miholje", "occ_en": "Michaelmas"}, {"slug": "gusjenica", "title_hr": "Gusjenica", "title_en": "The Caterpillar", "hr": ["Ja sam mala", "gusjenica.", "Jedem lišće,", "istina je cijela,", "no, list knjige", "đaka Marka", "nikad nisam jela."], "en": ["I'm a little", "caterpillar.", "I eat leaves,", "that's the whole truth, it's true,", "but the leaf", "of schoolboy Marko's book", "I never chew."], "day": "09-30"}, {"slug": "ugodno-druzenje-umirovljenika", "title_hr": "Ugodno druženje umirovljenika", "title_en": "A Pleasant Pensioners' Get-Together", "hr": ["Glazba svira, u srce me dira.", "Ej, ne svići skoro zlatna zoro.", "Bar da mi je svaki dan ovako,", "makar sutra ja sa kozom or'o."], "en": ["The music plays, and how it moves my heart!", "Hey, golden dawn, don't break so soon, I pray!", "If only every day could be like this —", "though I should plough with a goat the next day!"], "day": "10-01", "occ_hr": "Međunarodni dan starijih osoba", "occ_en": "International Day of Older Persons"}, {"slug": "da-spasimo-stare-obicaje", "title_hr": "Da spasimo stare običaje", "title_en": "Let Us Save the Old Customs", "hr": ["Ujesen bi ljudi kukuruze brali,", "uz vino i pjesmu doma komušali.", "Skupila se moba, veseli su bili,", "a dečki bi cure doma otpratili."], "en": ["In autumn people used to pick the maize", "and husk it, back at home, with wine and song;", "a moba gathered, merry, one and all,", "and then the lads would walk the girls back home."], "day": "10-02"}, {"slug": "zena", "title_hr": "Žena", "title_en": "Woman", "hr": ["Na krhkim plećima", "Planetu nosi.", "I bit će voljena", "Sve dok je živa."], "en": ["On her fragile shoulders", "she carries the planet.", "And she will be loved", "as long as she's alive."], "day": "10-03"}, {"slug": "pjesnicka-zadovoljstva", "title_hr": "Pjesnička zadovoljstva", "title_en": "The Poets' Pleasures", "hr": ["Sa svih strana dične Slavonije,", "svojoj duši pjesnik maštu dade:", "O ljepoti, o bolu, o ratu,", "netko ljubav, netko svoje jade."], "en": ["From every side of proud Slavonia", "the poet let his soul's own fancy flow:", "of beauty, and of pain, and of the war,", "one wrote of love, and one his grief and woe."], "day": "10-04"}, {"slug": "sto-je-najbrze", "title_hr": "Što je najbrže", "title_en": "What Is Fastest?", "hr": ["\"Najbrže su, djeco, misli,", "one se baš svega sjete.\"", "Mudro reče nastavnica:", "\"Misli među zvijezde lete.\""], "en": ["\"Fastest, children, are our thoughts;", "they can think of everything,\"", "wisely then the teacher said.", "\"Thoughts among the stars take wing.\""], "day": "10-05", "occ_hr": "Dan učitelja", "occ_en": "Teachers' Day"}, {"slug": "sokica", "title_hr": "Šokica", "title_en": "Šokica", "hr": ["Ej Šokice, milo moje janje,", "na jesen te vodim na vjenčanje."], "en": ["Hey, Šokica, my little lamb, you'll see:", "come the autumn, you'll be wed to me."], "day": "10-06"}, {"slug": "zelim-da-se-moj-glas-cuje", "title_hr": "Želim da se moj glas čuje", "title_en": "I Want My Voice to Be Heard", "hr": ["U veselju toga skupa,", "i dok glazba tiho svira,", "sretna djeca s balonima", "poruku su slali mira."], "en": ["In the gladness of that meeting,", "while the music played so soft,", "happy children with balloons", "sent a message of peace aloft."], "day": "10-07"}, {"slug": "sva-godisnja-doba", "title_hr": "Sva godišnja doba", "title_en": "All the Seasons", "hr": ["Ali nakon sreće i bol mora doći.", "U moj život tiho jesen se uvukla.", "Ovi tmurni dani nikad neće proći.", "Kao list sa stabla srce mi je svukla."], "en": ["But after happiness, the pain must also come;", "and into my life, so quietly, the autumn crept.", "These gloomy days will never pass, not one;", "it stripped my heart, as from a tree a leaf is swept."], "day": "10-08"}, {"slug": "blago-meni-jer-me-majka-zeni", "title_hr": "Blago meni, jer me majka ženi", "title_en": "Lucky Me, My Mother's Marrying Me Off", "hr": ["Jednog dana, majka veli meni:", "„Dragi, sine, hajde se oženi!", "Stigla jesen, uskoro će zima,", "a u Sopju lijepih cura ima.“"], "en": ["One day my mother said to me: \"My son,", "my dear, come on and marry, get it done!", "The autumn's here, and soon the winter's due,", "and Sopje has its pretty girls, it's true.\""], "day": "10-09"}, {"slug": "ovaj-dom-je-utociste-vase", "title_hr": "Ovaj dom je utočište vaše", "title_en": "This Home Is Your Refuge", "hr": ["Sjetite se kad ste mladi bili", "i ljubavne snove dok ste snili.", "I starost je ljepša kad se druži,", "to druženje Dom će da vam pruži."], "en": ["Remember when you once were young, and when", "you dreamed the dreams of love you dreamed back then.", "Old age is sweeter, too, in company,", "and that the Home will give you, you will see."], "day": "10-10"}, {"slug": "zov-domovine", "title_hr": "Zov domovine", "title_en": "The Call of the Homeland", "hr": ["Rođena ti gruda sreću, ljubav daje,", "svako drvo, kamen, dječje radovanje.", "To ti tuđa zemlja nikad neće dati.", "Maćeha se majkom nikad neće zvati."], "en": ["The soil where you were born gives love and joy,", "each tree, each stone, the gladness of a boy;", "no foreign land will give you this, no other:", "a stepmother will never be called mother."], "day": "10-11"}, {"slug": "prodajem-frizider-gorenje", "title_hr": "Prodajem frižider Gorenje", "title_en": "Gorenje Freezer for Sale", "hr": ["Da ujesen kupiš sebi gicu", "i jeftino imaš ledenicu."], "en": ["So in the autumn you can buy a pig,", "and have a freezer cheaply, nice and big."], "day": "10-12"}, {"slug": "pitas-me", "title_hr": "Pitaš me", "title_en": "You Ask Me", "hr": ["Još da mogu da poljubim,", "tvoja medna usta mala.", "Vjeruj, dušo, da bi tada", "moja pjesma sama cvala."], "en": ["If, besides, I could but kiss", "your small mouth, so honey-sweet,", "trust me, darling, then my poem", "of itself would bloom, complete."], "day": "10-13"}, {"slug": "neposlusni-vrabac", "title_hr": "Neposlušni vrabac", "title_en": "The Disobedient Sparrow", "hr": ["U ovoj priči ima", "nešto vrjednije od zlata:", "nije vam svatko prijatelj", "tko vas vadi iz blata."], "en": ["In this story there is something", "more precious than pure gold:", "not all who pull you from the mud", "are friends of yours, all told."], "day": "10-14"}, {"slug": "zivot-penzionera", "title_hr": "Život penzionera", "title_en": "A Pensioner's Life", "hr": ["Cijelo vrijeme mašta, sanja,", "što će moći sve da kupi.", "\"Kupit ću si drva sada,", "dok još zima ne nastupi.\""], "en": ["All the time he dreams and muses", "what he'll buy, the things he'll get:", "\"Now I'll buy myself some firewood,", "while the winter's not here yet.\""], "day": "10-15"}, {"slug": "zasto-covjek-nije-kao-dijete", "title_hr": "Zašto čovjek nije kao dijete", "title_en": "Why Is Man Not Like a Child", "hr": ["Zašto čovjek nije kao dijete", "što koru kruha među sobom dijeli?", "Zašto mnogi zemaljsko blago", "samo za sebe želi?"], "en": ["Why is man not like a child", "that will share its crust with friends?", "Why do many want earth's riches", "only for their selfish ends?"], "day": "10-16", "occ_hr": "Svjetski dan kruha · napisano na današnji dan, 1975.", "occ_en": "World Bread Day · written on this day in 1975"}, {"slug": "ne-mogu-te-zaboraviti", "title_hr": "Ne mogu te zaboraviti", "title_en": "I Cannot Forget You", "hr": ["Ja nikada ne ću zaboravit moći,", "sa tvojega lica kad pročitah sreću.", "I nikada s drugom sretan biti ne ću,", "kao s tobom svake provedene noći."], "en": ["I never, ever shall be able to forget", "the happiness I read upon your face;", "and never with another in your place", "be happy as with you, each night we met."], "day": "10-17"}, {"slug": "dragutinu-gibicaru", "title_hr": "Dragutinu Gibičaru", "title_en": "To Dragutin Gibičar", "hr": ["Da imadem dobrog prijatelja,", "oduvijek sam ja u duši snio."], "en": ["To have a friend, a good one, all my own,", "was what my soul had dreamed, time and again."], "day": "10-18"}, {"slug": "sva-godisnja-doba", "title_hr": "Sva godišnja doba", "title_en": "All the Seasons", "hr": ["U ljubavi našoj sve do ovih dana.", "Sva godišnja doba prošla su kroz mene.", "Od najljepše sreće pa do bolnih rana.", "Od žarkoga ljeta do zime studene."], "en": ["In our love, right up until these days,", "all the seasons of the year have passed through me:", "from the loveliest of joys to aching wounds,", "from the burning summer to the winter's freeze."], "day": "10-19", "occ_hr": "napisano na današnji dan, 1974.", "occ_en": "written on this day in 1974"}, {"slug": "volim-te-lavicu", "title_hr": "Volim te laviću", "title_en": "I Love You, Little Lion", "hr": ["Koliko si puta,", "draga, meni rekla:", "volim te laviću!", "Dok je Drava tekla."], "en": ["How often, my darling,", "you told me, you'd say:", "\"I love you, little lion!\"", "while the Drava flowed away."], "day": "10-20", "occ_hr": "napisano na današnji dan, 1974.", "occ_en": "written on this day in 1974"}, {"slug": "pod-krosnjom-kestena", "title_hr": "Pod krošnjom kestena", "title_en": "Under the Chestnut's Crown", "hr": ["Tada pčele cvijet oplode,", "iza cvijeta plod urodi,", "a s jeseni, kad sazori,", "najljepše je u prirodi."], "en": ["Bees then pollinate the blossom,", "after blossom, fruit will grow,", "and in autumn, when it's ripened,", "nature has no finer show."], "day": "10-21", "occ_hr": "napisano na današnji dan, 2010.", "occ_en": "written on this day in 2010"}, {"slug": "ja-volim-nadu", "title_hr": "Ja volim Nadu", "title_en": "I Love Nada", "hr": ["Vjerujete mi, dečki,", "nisam više dijete.", "Ja volim Nadu", "iz klupe pete!"], "en": ["Believe me, lads,", "I'm no kid now, I swear.", "I love Nada,", "fifth desk, over there!"], "day": "10-22"}, {"slug": "domovino-moja", "title_hr": "Domovino moja", "title_en": "My Homeland", "hr": ["Zemljo moja, srcu najmilija,", "ja sam tebi dao zavjet sveti:", "Ako treba, život ću ti dati,", "tu sam rođen, tu ću i umrijeti!"], "en": ["My land, the dearest to my heart of all,", "to you I made a sacred vow, that I,", "if need be, would give up my life for you:", "here I was born, and here I'll also die!"], "day": "10-23"}, {"slug": "od-djetinjstva-do-starackih-dana", "title_hr": "Od djetinjstva do staračkih dana", "title_en": "From Childhood to Old Age", "hr": ["I starački dovukli se dani,", "ni Amora ne sretnem k'o prije.", "Srce mi je kao nekad gordo,", "još ga starost ukrotila nije."], "en": ["Now the days of old age have dragged in,", "and I meet Amor less — it's not the same;", "yet my heart is proud, as once it was —", "that's a thing old age has yet to tame."], "day": "10-24"}, {"slug": "sumski-kralj", "title_hr": "Šumski kralj", "title_en": "The Forest King", "hr": ["To su, djeco,", "žir i hrast:", "svaki sin mu", "kapu nosi,", "dok oluji", "hrast prkosi."], "en": ["Children, it's", "the acorn and the oak:", "every son", "wears a cap, it's true,", "while the oak", "stands the storm right through."], "day": "10-25"}, {"slug": "podravino-diko-moja", "title_hr": "Podravino, diko moja", "title_en": "Podravina, My Pride", "hr": ["Da ozarim Sopju lice", "kao pjesnik, ja ću znati.", "Svojim srcem, svojim perom,", "svu ljepotu ću mu dati."], "en": ["How to light up Sopje's face,", "as a poet, I will know:", "with my heart and with my pen", "all its beauty I'll bestow."], "day": "10-26"}, {"slug": "ni-postaru-nije-lako", "title_hr": "Ni poštaru nije lako", "title_en": "It's Not Easy for the Postman Either", "hr": ["Nekad sunce, nekad kiše,", "nekad torbu tegli više.", "Ni poštaru nije lako,", "to ne može biti svatko!"], "en": ["Sometimes sun, and sometimes rain,", "sometimes more to haul, it's true.", "Nor has the postman got it sweet —", "not just anyone would do!"], "day": "10-27", "occ_hr": "napisano na današnji dan, 2012.", "occ_en": "written on this day in 2012"}, {"slug": "toplice", "title_hr": "Toplice!", "title_en": "The Spa!", "hr": ["Svima je tijelo slabo,", "od bola satrveno,", "ali je duša mlada.", "Želja za zdravljem", "i životom", "svima je tako jaka."], "en": ["All of them weak in body,", "ground down by pain,", "but young in soul.", "The wish for health", "and for life", "is so strong in all of them."], "day": "10-28"}, {"slug": "bol-kroz-zivot", "title_hr": "Bol kroz život", "title_en": "A Lifetime of Pain", "hr": ["Ljudima si puno puta,", "u pomoći, Gospo, bila,", "iako si i ti gorke,", "na svom putu suze lila!"], "en": ["Many times you've been, Our Lady,", "help to people in their need,", "though you too along your journey", "shed your bitter tears indeed!"], "day": "10-29"}, {"slug": "nela", "title_hr": "Nela!", "title_en": "Nela!", "hr": ["Kad Ti Muze maštu pruže", "i životne cvatu ruže,", "nova pjesma kad se javi,", "na papir je odmah stavi."], "en": ["When the Muses lend you fancy", "and life's roses are in bloom,", "when a new poem comes a-calling,", "set it down on paper soon."], "day": "10-30", "occ_hr": "napisano na današnji dan, 2013.", "occ_en": "written on this day in 2013"}, {"slug": "cvjetni-san", "title_hr": "Cvjetni san", "title_en": "A Dream of Flowers", "hr": ["Sve je tako brzo prošlo,", "kao vjetrom odnesen dan,", "i cvijeće sa tog prozora", "za mene je ostao san."], "en": ["All of it has passed so quickly,", "like a day the wind has swept,", "and the flowers at that window", "only in my dreams are kept."], "day": "10-31"}, {"slug": "pjesnikova-zelja-2", "title_hr": "Pjesnikova želja", "title_en": "The Poet's Wish", "hr": ["Jednom kada odem", "u rajska blaženstva", "ponekada dođi,", "moj grob obiđi."], "en": ["Some day, when I've gone", "to the bliss of heaven,", "now and then, come round,", "visit where I lie."], "day": "11-01", "occ_hr": "Svi sveti", "occ_en": "All Saints' Day"}, {"slug": "najdrazima-ja-darujem-dusu", "title_hr": "Najdražima ja darujem dušu", "title_en": "To My Dearest I Give My Soul", "hr": ["Prošao je život kao jeka", "i odnio dio naših snova."], "en": ["My life has passed, as echoes pass away,", "and carried off a part of all our dreams."], "day": "11-02", "occ_hr": "Dušni dan", "occ_en": "All Souls' Day"}, {"slug": "pjesma-valpovu", "title_hr": "Pjesma Valpovu", "title_en": "A Song to Valpovo", "hr": ["Dođe jesen i lišće uvene,", "dani kratki, a noć je velika.", "Kada mi se sklope oči snene,", "Valpovo je opet meni dika."], "en": ["Autumn comes, the leaves begin to wither,", "short the days, the night is vast and wide;", "when my drowsy eyes at last are closing,", "Valpovo once more remains my pride."], "day": "11-03", "occ_hr": "napisano na današnji dan, 1974.", "occ_en": "written on this day in 1974"}, {"slug": "sve-dane-moje", "title_hr": "Sve dane moje", "title_en": "All My Days", "hr": ["Sve dane moje radosti,", "tebi sam, draga, dao.", "Najljepšu snagu mladosti,", "no, ipak mi nije žao."], "en": ["All the days of all my joy", "I have given, dear, to you,", "all the finest strength of youth —", "and yet I do not rue."], "day": "11-04"}, {"slug": "anice", "title_hr": "Anice", "title_en": "To Anica", "hr": ["Ovaj život kao rijeka teče", "i odnosi dio naših snova.", "Kap veselja od srca ti želim,", "tvojoj sreći i ja se veselim."], "en": ["This life of ours flows onward like a river", "and carries off a part of all our dreams.", "I wish you, from my heart, a drop of joy,", "and in your happiness I too rejoice."], "day": "11-05", "occ_hr": "napisano na današnji dan, 2010.", "occ_en": "written on this day in 2010"}, {"slug": "koza-i-sedam-kozlica", "title_hr": "Koza i sedam kozlića", "title_en": "The Goat and the Seven Kids", "hr": ["Prodao sam kupus, Bogu hvala,", "kupus ode, al' koza ostala."], "en": ["I've sold the cabbage — God be thanked — but note:", "the cabbage went, and left me with the goat."], "day": "11-06", "occ_hr": "napisano na današnji dan, 2000.", "occ_en": "written on this day in 2000"}, {"slug": "nudim-burad-za-rakiju", "title_hr": "Nudim burad za rakiju", "title_en": "Rakija Barrels on Offer", "hr": ["Došle godine i na moja vrata.", "Puno se toga iz života briše.", "Zato ja ovaj oglas sad dajem,", "jer mnoge stvari ne trebam više."], "en": ["The years have come to my door too, at last;", "so much of life is rubbed out, gone, and past.", "That's why I'm placing this advertisement now:", "there's lots I need no longer, anyhow."], "day": "11-07"}, {"slug": "dao-sam-ti-boli", "title_hr": "Dao sam ti boli", "title_en": "I Gave You Pain", "hr": ["Kazni me, odbaci, prezri", "i to bih sve prebolio,", "no, nikada nemoj reći,", "da nisam te ludo volio."], "en": ["Punish, cast me off, and scorn me —", "all of that I could live through;", "but you must not ever say", "that I did not madly love you."], "day": "11-08"}, {"slug": "san-o-sreci", "title_hr": "San o sreći", "title_en": "A Dream of Happiness", "hr": ["A ja malen još nejačak,", "daleki sam snio sanak.", "U mašti sam sretan bio,", "a na javi plaćo danak."], "en": ["And I, little, still a weakling,", "dreamed a dream of far away.", "In my fancies I was happy,", "but awake, I had to pay."], "day": "11-09"}, {"slug": "etno-kuca-semialjac-kate", "title_hr": "Etno kuća Semialjac Kate", "title_en": "Kata Semialjac's Ethno House", "hr": ["Kuhinja je ista kao prije:", "žena muža sa objedom čeka,", "prije ručka rakija se pije,", "pa večera i postelja meka."], "en": ["The kitchen is the same as it once was:", "the wife awaits her husband, dinner made;", "before the meal they drink their rakija,", "then supper comes, and a soft bed is laid."], "day": "11-10"}, {"slug": "kad-kocije-zasviraju", "title_hr": "Kad Kočije zasviraju", "title_en": "When Kočije Strike Up", "hr": ["Kad Martinje kaže svoje,", "pravo vino je u čaši.", "A „KOČIJE“ tada poje:", "„DOBRO VINO TAMBURAŠI“!"], "en": ["When St Martin has his say,", "real wine's in the glass again;", "and Kočije sing out then:", "“Good Wine, You Tambura Men!”"], "day": "11-11", "occ_hr": "Martinje · napisano na današnji dan, 2014.", "occ_en": "St Martin's Day · written on this day in 2014"}, {"slug": "uslisi-me-boze", "title_hr": "Usliši me, Bože", "title_en": "Hear Me, O God", "hr": ["Možda ima kakav skromni kutić", "i to je, Bože, dovoljno za me.", "Stisnut ću se kao suhi prutić,", "usko je moje staračko rame."], "en": ["Perhaps there is some corner, not too big,", "and that, O God, would be enough for me.", "I'll squeeze in there, as thin as a dry twig:", "my aged shoulder's narrow as can be."], "day": "11-12", "occ_hr": "napisano na današnji dan, 2012.", "occ_en": "written on this day in 2012"}, {"slug": "volio-bih-da-sam-vjetar", "title_hr": "Volio bih da sam vjetar", "title_en": "I Wish I Were the Wind", "hr": ["Oh, da mogu biti vjetar!", "Koliko li za me sreće?", "Poljupcima prije snova,", "sklapao bih dragoj vjeđe."], "en": ["Oh, if I could be the wind!", "Oh, the happiness I'd know!", "With my kisses, ere she dreams,", "I would close her eyelids so."], "day": "11-13"}, {"slug": "neposlusni-vrabac", "title_hr": "Neposlušni vrabac", "title_en": "The Disobedient Sparrow", "hr": ["Kad netko visoko leti", "i uživa lude slasti,", "tko je drzak i zločest,", "taj može nisko pasti."], "en": ["When someone flies up high", "and revels in wild delight,", "if he's cheeky and naughty,", "he can fall from that height."], "day": "11-14"}, {"slug": "sokadijo-moj-voljeni-kraju", "title_hr": "Šokadijo moj voljeni kraju", "title_en": "Šokadija, My Beloved Land", "hr": ["Volim tebe mili zavičaju,", "jer sam rođen u tvojemu kraju.", "Da se rodim opet bi tvoj bio", "i šokicu dragu oženio."], "en": ["I love you, native land so dear to me,", "for in your region I was born, you see;", "were I reborn, I'd still be yours, and then", "I'd wed a dear Šokica once again."], "day": "11-15"}, {"slug": "zeni-za-rodendan", "title_hr": "Ženi za rođendan", "title_en": "To My Wife on Her Birthday", "hr": ["Na tom putu što me pratiš,", "od svega ti srca hvala!", "A dvoje si divne djece,", "meni, dušo, darovala."], "en": ["For the road you've walked beside me,", "all my heartfelt thanks are due;", "and two lovely children, darling,", "were the gift I had from you."], "day": "11-16", "occ_hr": "napisano na današnji dan, 2007.", "occ_en": "written on this day in 2007"}, {"slug": "sokacki-obicaji", "title_hr": "Šokački običaji", "title_en": "Šokac Customs", "hr": ["Nema više konja da dvorištem njište,", "mjesto njih traktori sokacima bruje.", "Nema mladih snaša da u kolu vrište,", "sve je utihnulo, ništa se ne čuje."], "en": ["There are no more horses to neigh in the yard,", "instead of them tractors go droning down lanes;", "no young wives are left in the kolo to shriek,", "all has fallen silent, and no sound remains."], "day": "11-17"}, {"slug": "vojnikova-majka", "title_hr": "Vojnikova majka", "title_en": "The Soldier's Mother", "hr": ["Ubiše mi sina,", "od osamnaest godina.", "Život je izgubio u boju,", "braneći domovinu svoju."], "en": ["They killed my son,", "eighteen years old.", "He lost his life in battle,", "defending his homeland."], "day": "11-18", "occ_hr": "Dan sjećanja na Vukovar", "occ_en": "Vukovar Remembrance Day"}, {"slug": "starac", "title_hr": "Starac!", "title_en": "The Old Man", "hr": ["Vrati bože, osmjeh, radost,", "svakom stvoru da se divim.", "Slatku ljubav, sretnu mladost", "još jedanput da proživim."], "en": ["Give me back, O God, my smile", "and the joy to marvel still;", "sweetest love and youth — a while", "let me live them, if you will."], "day": "11-19"}, {"slug": "komplet-za-kolinje", "title_hr": "Komplet za kolinje", "title_en": "A Kolinje Kit", "hr": ["Ovo dajem da pomognem gici,", "da se brzo nađe u pušnici."], "en": ["I'm selling this to help the piggy, so", "into the smokehouse quickly she will go."], "day": "11-20", "occ_hr": "napisano na današnji dan, 2000.", "occ_en": "written on this day in 2000"}, {"slug": "prijatelju-dokonalu", "title_hr": "Prijatelju Dokonalu!", "title_en": "To My Friend Dokonal!", "hr": ["Ovo divno prijateljstvo,", "što je časno među nama,", "ta suradnja obostrana,", "neka traje godinama."], "en": ["This fine friendship that we share,", "held in honour by us two,", "and our working hand in hand —", "may it last the long years through."], "day": "11-21", "occ_hr": "napisano na današnji dan, 2013.", "occ_en": "written on this day in 2013"}, {"slug": "sretan-imendan-priji-kati", "title_hr": "Sretan imendan priji Kati", "title_en": "A Happy Name Day to Our Prija Kata", "hr": ["Mili, Bože, što godine lete,", "pa na pleća kao teret slete.", "Zima tiho kuca mi na vrata,", "eto stiže već i sveta Kata."], "en": ["Dear God, how swiftly all the years fly by,", "and on our shoulders like a burden lie;", "the winter's softly knocking at my door,", "and here's Saint Kata, come around once more."], "day": "11-22", "occ_hr": "napisano na današnji dan, 2011.", "occ_en": "written on this day in 2011"}, {"slug": "rodena-gruda", "title_hr": "Rođena gruda", "title_en": "Native Soil", "hr": ["Ništa nema ljepše od svojega kraja", "jer tuđina često znade da zaboli."], "en": ["There's nothing lovelier — you'll surely understand —", "than home, for foreign lands can often do you wrong."], "day": "11-23"}, {"slug": "treca-dob-u-dnevnom-boravku", "title_hr": "Treća dob u „Dnevnom boravku“", "title_en": "The Third Age at the \"Day Centre\"", "hr": ["Ponekada nešto rade,", "vezenjem se neke bave,", "al' godine brzo lete,", "pa rođendan često slave."], "en": ["Now and then they do some work;", "some embroider, it is true;", "but the years go flying fast,", "birthdays come round often, too."], "day": "11-24", "occ_hr": "napisano na današnji dan, 2013.", "occ_en": "written on this day in 2013"}, {"slug": "uspavanka", "title_hr": "Uspavanka", "title_en": "Lullaby", "hr": ["Čeka te čarobna", "ljuljačka snova,", "u san te uljulja", "uspavanka ova."], "en": ["A magical swing", "of dreams waits for you,", "and this lullaby rocks you", "to sleep, as lullabies do."], "day": "11-25"}, {"slug": "sopje-selo-moga-djetinjstva", "title_hr": "Sopje, selo moga djetinjstva", "title_en": "Sopje, Village of My Childhood", "hr": ["Još se sjećam svog djetinjstva,", "divna nošnja se nosila,", "što je bila ukras selu,", "folkloraše okitila."], "en": ["I recall my childhood still:", "lovely costume then was worn,", "the adornment of the village,", "and the dancers it adorned."], "day": "11-26", "occ_hr": "napisano na današnji dan, 2010.", "occ_en": "written on this day in 2010"}, {"slug": "kceri-mila", "title_hr": "Kćeri mila", "title_en": "Dear Daughter", "hr": ["Za tvoj dragi rođendan,", "nemam ništa da ti dam.", "Već ti dajem pregršt želja", "za dug život pun veselja."], "en": ["For your dear birthday, I say,", "I have nothing to give away.", "But a handful of wishes I send", "for a long life, joy without end."], "day": "11-27"}, {"slug": "bol-kroz-zivot", "title_hr": "Bol kroz život", "title_en": "A Lifetime of Pain", "hr": ["Trpio sam mnogo bola,", "na svom putu punom jada,", "Bog mi bio u pomoći,", "od djetinjstva sve do sada."], "en": ["I have suffered so much pain", "on my road so full of woe;", "God has always been my helper,", "from a child till now, I know."], "day": "11-28"}, {"slug": "oj-oraje-oraje", "title_hr": "Oj, oraje, oraje", "title_en": "Oh, Walnut, Walnut Tree", "hr": ["Još mi baba kaže:", "e, moj djeda sijedi,", "ni oraha ljuska,", "više ti ne vrijedi."], "en": ["And granny tells me too:", "\"Eh, my grandad grey,", "not even a walnut shell's", "of use to you today.\""], "day": "11-29", "occ_hr": "napisano na današnji dan, 2011.", "occ_en": "written on this day in 2011"}, {"slug": "dobro-dosli-prijatelji-dragi", "title_hr": "Dobro došli prijatelji dragi!", "title_en": "Welcome, My Dear Friends!", "hr": ["U Belišću pedeset i prve,", "dva pupoljka bila su na radu.", "Jednog dana tu se upoznali,", "jedno drugom svoje srce dali."], "en": ["In Belišće, in nineteen fifty-one,", "two buds were working there, side by side.", "And there they met one day, and from the start", "each one gave to the other one their heart."], "day": "11-30"}, {"slug": "molim-paket-djeda-mraze", "title_hr": "Molim paket Djeda Mraze!", "title_en": "A Parcel, Please, Grandfather Frost!", "hr": ["Molim paket Djeda Mraze!", "Ja sam ti još sasvim mala.", "Zato ništa drugo ne znam,", "Nego reći: Lijepo hvala!"], "en": ["Please, Grandfather Frost, a parcel!", "I am still so very small.", "That is why I know no more", "than to say: \"Thank you!\" — that's all."], "day": "12-01"}, {"slug": "imam-zensku-bundu-za-prodaju", "title_hr": "Imam žensku bundu za prodaju", "title_en": "Lady's Fur Coat for Sale", "hr": ["Stigla zima i godina nova,", "za prodaju bundica je ova.", "Nije stara, al' ni nova nije,", "topla bunda k'o pećica grije."], "en": ["The winter's here, the New Year's on its way,", "and so this little coat's for sale today.", "It isn't old — but new it isn't, quite;", "it warms you like a little stove, just right."], "day": "12-02"}, {"slug": "sopje-nekada-i-sada", "title_hr": "Sopje nekada i sada", "title_en": "Sopje, Then and Now", "hr": ["Daleko sam od mog sela,", "al' me srce k njemu vuče.", "Još se sjećam onih dana,", "kad sam bio tu kod kuće."], "en": ["I'm far off from my own village,", "but my heart still draws me near.", "I still well recall the days", "when I was at home, right here."], "day": "12-03"}, {"slug": "ovaj-dom-je-utociste-vase", "title_hr": "Ovaj dom je utočište vaše", "title_en": "This Home Is Your Refuge", "hr": ["Kad vas jutro iz toplog sna budi", "i kad danak na ljepotu sluti,", "a prijatelj kraj tebe nasmije,", "eto, to su životne premije."], "en": ["When morning wakes you from a cosy sleep,", "the day foretelling beauty on its way,", "and when a friend beside you gives a smile,", "why, those are bonuses that life will pay."], "day": "12-04", "occ_hr": "napisano na današnji dan, 2013.", "occ_en": "written on this day in 2013"}, {"slug": "cekao-sam-tebe", "title_hr": "Čekao sam tebe!", "title_en": "I Waited for You!", "hr": ["Tražio sam, draga, tvoje mile oči,", "što me toplo griju u studenoj noći.", "I medene usne, tvoga slatkog smijeha,", "poljubaca pune i čedne bez grijeha."], "en": ["I sought, my darling, for your dear eyes' light,", "that warms me through and through in the cold night,", "and for your honeyed lips, where your sweet laughs begin,", "so full of kisses, chaste and free of sin."], "day": "12-05"}, {"slug": "djecji-snovi", "title_hr": "Dječji snovi", "title_en": "Children's Dreams", "hr": ["Zapamtite, tko je mio", "taj po noći divno sanja,", "ali tko je zločest bio,", "toga ljuta šiba ganja."], "en": ["So remember: those who're good", "have sweet dreams the whole night through;", "but the naughty ones will find", "that the stinging switch pursues."], "day": "12-06", "occ_hr": "Sveti Nikola", "occ_en": "St Nicholas' Day"}, {"slug": "osvrt-na-ljubav", "title_hr": "Osvrt na ljubav", "title_en": "A Look at Love", "hr": ["Sretan mačor u krevetu prede,", "sve što treba u krilašcu nađe,", "tu su snovi koji zlata vrijede,", "ništa nema od ljubavi slađe."], "en": ["A happy tomcat purrs upon the bed,", "in a little lap he finds all that he needs;", "here are the dreams worth their weight in gold,", "and nothing's sweeter than love, indeed."], "day": "12-07", "occ_hr": "napisano na današnji dan, 2012.", "occ_en": "written on this day in 2012"}, {"slug": "ne-budi-me-majko-rano", "title_hr": "Ne budi me, majko, rano", "title_en": "Don't Wake Me Early, Mother", "hr": ["Ne budi me, majko, rano.", "Ne kidaj mi divne snove,", "kada zoveš moje ime,", "mislim da me draga zove."], "en": ["Mother, do not wake me early,", "do not tear apart my dreams:", "when I hear you call my name out,", "it's my darling's voice, it seems."], "day": "12-08"}, {"slug": "obitelji-nikolic", "title_hr": "Obitelji Nikolić!", "title_en": "To the Nikolić Family!", "hr": ["I kada se igra", "i po sobi skače,", "baki srce udara", "od veselja jače."], "en": ["And when he plays", "and hops about the floor,", "Grandma's heart beats", "with joy all the more."], "day": "12-09"}, {"slug": "tuzno-je-biti-sam", "title_hr": "Tužno je biti sam", "title_en": "It's Sad to Be Alone", "hr": ["Zato si nađi,", "životnog druga,", "nikad ne budi sam.", "Život je slađi,", "manja je tuga,", "vjeruj mi,", "ja to znam."], "en": ["So go out and find", "a companion true,", "never be alone.", "Life's sweeter, you'll find,", "and less sorrow, too —", "trust me,", "this I know."], "day": "12-10", "occ_hr": "napisano na današnji dan, 1989.", "occ_en": "written on this day in 1989"}, {"slug": "orasi-su-za-praznik-u-modi", "title_hr": "Orasi su za praznik u modi", "title_en": "Walnuts Are in Fashion for the Holidays", "hr": ["Ide Božić i Nova godina,", "doček gosti prava je milina."], "en": ["Christmas is coming, and the New Year too;", "to welcome guests is a delight, it's true."], "day": "12-11", "occ_hr": "napisano na današnji dan, 2000.", "occ_en": "written on this day in 2000"}, {"slug": "za-prodaju-imam-naftaricu", "title_hr": "Za prodaju imam naftaricu", "title_en": "Oil Heater for Sale", "hr": ["Ne daj Bože, da se tko smrzava,", "dok pećica u garaži spava."], "en": ["Now God forbid that anyone should freeze", "while in the garage this small stove sleeps at ease."], "day": "12-12"}, {"slug": "sveta-lucija", "title_hr": "Sveta Lucija", "title_en": "Saint Lucy", "hr": ["Svima vama što ste u toj tami", "usamljeni u životu sami,", "nek' vam teku u ljepoti dani,", "od LUCIJE SVETE OBASJANI."], "en": ["To all of you who in that darkness stay,", "alone and lonely all along life's way,", "may all your days in beauty flow and run,", "lit up by Holy Lucy, every one."], "day": "12-13", "occ_hr": "Sveta Lucija", "occ_en": "St Lucy's Day"}, {"slug": "moj-voljeni-grade", "title_hr": "Moj voljeni grade", "title_en": "My Beloved Town", "hr": ["Oj, Valpovo, moj voljeni grade,", "ti mi rasteš kao vita jela,", "na njedrima divne Slavonije,", "ljepota me tvoja zanijela."], "en": ["O Valpovo, my own beloved town,", "you grow for me just like a slender fir,", "upon the breast of fair Slavonia;", "your beauty sets my very heart astir."], "day": "12-14"}, {"slug": "protiv-svoje-volje", "title_hr": "Protiv svoje volje", "title_en": "Against My Will", "hr": ["Kad sam bio u trbuhu majke,", "nikada mi nije bilo bolje.", "Mene ništa ni pitali nisu,", "rodiše me protiv moje volje."], "en": ["When I was lying in my mother's womb,", "I never had it better; and yet, still,", "nobody even asked me what I wished:", "they brought me forth, and quite against my will."], "day": "12-15", "occ_hr": "napisano na današnji dan, 1990.", "occ_en": "written on this day in 1990"}, {"slug": "diljem-slavonije", "title_hr": "Diljem Slavonije", "title_en": "All Across Slavonia", "hr": ["U Kutjevu zaustavim vrijeme,", "pijuć' vino nekoliko dana,", "uz tambure i Šokice mlade,", "volim život i to mi je mana."], "en": ["In Kutjevo I make the time stand still,", "and drink the wine for several days away,", "with tamburas and with the young Šokice;", "I love life — that's my failing, I must say."], "day": "12-16", "occ_hr": "napisano na današnji dan, 1993.", "occ_en": "written on this day in 1993"}, {"slug": "dragice", "title_hr": "Dragice!", "title_en": "Dragica!", "hr": ["Kao rijeka bez povratka,", "isto tako život teče.", "Blago onom ljudskom stvoru,", "tko zdravstvene ima sreće."], "en": ["Like a river never turning", "back, so does our life flow on;", "blessed is the human creature", "who has health to count upon."], "day": "12-17", "occ_hr": "napisano na današnji dan, 2012.", "occ_en": "written on this day in 2012"}, {"slug": "cestitka-unucima", "title_hr": "Čestitka unucima", "title_en": "New Year's Greetings to Our Grandchildren", "hr": ["Dobro zdravlje pored svega,", "to je naša želja jaka!", "Sve najbolje vama žele", "vaši dobri djed i baka!"], "en": ["And good health above all things:", "that's our wish, both strong and true!", "All the best, your good grandpa", "and your good grandma wish to you!"], "day": "12-18", "occ_hr": "napisano na današnji dan, 1988.", "occ_en": "written on this day in 1988"}, {"slug": "djeda-mraz", "title_hr": "Djeda Mraz", "title_en": "Grandfather Frost", "hr": ["Djeda Mraze, dragi, mio,", "darove si nam donio.", "Gdje si tako dugo bio?", "Jesi li se umorio?"], "en": ["Grandfather Frost, so kind and dear,", "you have brought us presents here.", "Where've you been so long this year?", "Are you tired out, we fear?"], "day": "12-19"}, {"slug": "zanos", "title_hr": "Zanos", "title_en": "Rapture", "hr": ["Oh, ljubavi moja!", "Slatka si i mila,", "kao majka čedu,", "kad raširi krila."], "en": ["Oh, my love, my darling!", "Sweet you are, and mild,", "like a mother spreading", "her wings above her child."], "day": "12-20", "occ_hr": "napisano na današnji dan, 1973.", "occ_en": "written on this day in 1973"}, {"slug": "sretan-bozic", "title_hr": "Sretan Božić", "title_en": "Merry Christmas", "hr": ["Sretan Božić vama", "Ja iskreno želim.", "Poklonima vašim", "I ja se veselim."], "en": ["Merry Christmas to you all,", "I sincerely wish today;", "and I too will share your joy", "in the presents come your way."], "day": "12-21", "occ_hr": "napisano na današnji dan, 2012.", "occ_en": "written on this day in 2012"}, {"slug": "draga-generacijo", "title_hr": "Draga generacijo!", "title_en": "My Dear Generation!", "hr": ["Među ljudstvom neka sloga vlada", "Ne bilo vam staračkoga jada", "Da se lakše u životu diše", "I ratova da ne bude više."], "en": ["Among all folk may harmony hold sway,", "may sorrows of old age not come your way,", "that we may breathe more easily in life,", "and let there be no more of war and strife."], "day": "12-22", "occ_hr": "napisano na današnji dan, 2013.", "occ_en": "written on this day in 2013"}, {"slug": "dragi-denis", "title_hr": "Dragi Denis", "title_en": "Dear Denis", "hr": ["Neka ti Božić", "i godina Nova", "radosti pruže", "i dobro veselje,", "puno zdravlja,", "ostvarenje snova."], "en": ["May Christmas, and", "the New Year too,", "bring you gladness", "and good cheer,", "lots of health,", "and dreams come true."], "day": "12-23", "occ_hr": "napisano na današnji dan, 2005.", "occ_en": "written on this day in 2005"}, {"slug": "ide-bozic-i-sveti-nikola-i-poklona-nosi-puna-kola", "title_hr": "Ide Božić i sveti Nikola i poklona nosi puna kola", "title_en": "Here Come Christmas and Saint Nicholas with a Cartful of Gifts", "hr": ["Na Badnjak smo sretni bili", "i božićni bor kitili.", "Stavljali smo sve ukrase,", "još jabuke i orase."], "en": ["Christmas Eve, how glad were we,", "trimming up the Christmas tree!", "All the baubles, every one,", "apples, walnuts too, we hung."], "day": "12-24", "occ_hr": "Badnjak", "occ_en": "Christmas Eve"}, {"slug": "gospodi-ani-gillinger-iz-ivankova", "title_hr": "Gospođi Ani Gillinger iz Ivankova", "title_en": "To Mrs Ana Gillinger of Ivankovo", "hr": ["Nek' Vam bude SRETAN BOŽIĆ", "I GODINA ova NOVA,", "a najviše dobrog zdravlja:", "želi Ivo iz Valpova!"], "en": ["Have a very Merry Christmas", "and a happy New Year so,", "but above all, good health too:", "wishes Ivo of Valpovo!"], "day": "12-25", "occ_hr": "Božić", "occ_en": "Christmas Day"}, {"slug": "kolinje-u-drenovcima", "title_hr": "Kolinje u Drenovcima", "title_en": "Kolinje in Drenovci", "hr": ["Došla zima, zabijelilo inje,", "najvažnije sada je kolinje.", "Valja čuvat stare običaje,", "spremit meso dok zima još traje."], "en": ["Winter has come, the hoarfrost's turned things white;", "kolinje matters most now, as is right.", "The good old customs must be kept, we say,", "and meat put by while winter's here to stay."], "day": "12-26", "occ_hr": "Sveti Stjepan · napisano na današnji dan, 2004.", "occ_en": "St Stephen's Day · written on this day in 2004"}, {"slug": "noge-bose-a-cipele-cure", "title_hr": "Noge bose a cipele cure", "title_en": "Bare Feet and Leaky Shoes", "hr": ["Pukla mi je cipela na peti,", "pa mi stalno rupa na pameti.", "Rupu gledam, mislim sad je zgoda,", "pa popravim dok ne uđe voda."], "en": ["My shoe's split open at the heel, you'll find,", "and so a hole is always on my mind.", "I eye the hole and think: now is the day", "to fix it, before water finds its way."], "day": "12-27", "occ_hr": "napisano na današnji dan, 1996.", "occ_en": "written on this day in 1996"}, {"slug": "sretna-vam-nova-godina-draga-generacijo", "title_hr": "Sretna vam Nova godina, draga generacijo", "title_en": "A Happy New Year to You, Dear Generation", "hr": ["Uskoro nam stiže Novo Ljeto,", "što nam nosi neka bude sretno,", "puno sreće i zdravlja i para,", "sve probleme nek' odnese stara."], "en": ["The New Year's soon upon us: may it be", "that all it brings is happy for you and me,", "with lots of luck and health and cash to hold;", "may all our troubles go off with the old."], "day": "12-28"}, {"slug": "hej-zivote", "title_hr": "Hej živote", "title_en": "Hey There, Life", "hr": ["Hej živote, malo stani!", "Sretna zoro, daj osvani!", "Radosnice, suzo, kani!", "Da nam budu ljepši dani.", "Dobro zdravlje, sreće puno,", "povrh svega, zlatno runo!"], "en": ["Hey there, life, slow down, stand still!", "Happy dawn, rise up — you will!", "Tears of joy, come fall your fill,", "so our days grow brighter still.", "Health and happiness in store,", "and the Golden Fleece, what's more!"], "day": "12-29"}, {"slug": "cestitka-unucima", "title_hr": "Čestitka unucima", "title_en": "New Year's Greetings to Our Grandchildren", "hr": ["Godinicu sretnu Novu,", "čestitamo vama svima!", "I darova puna kola,", "našim dragim unucima!"], "en": ["Happy little New Year: this", "we wish every one of you!", "And a cartload full of gifts", "for our dear grandchildren too!"], "day": "12-30"}, {"slug": "novogodisnje-zelje", "title_hr": "Novogodišnje želje", "title_en": "New Year's Wishes", "hr": ["Novo ljeto kad ura najavi,", "da sam s tobom i da se veselim,", "kad se radost na tom svijetu slavi,", "da ti prvi čestitke poželim."], "en": ["When the clock rings in the year that's new,", "may I be at your side, rejoicing here;", "when joy is celebrated the whole world through,", "may I be first to wish you a happy year."], "day": "12-31", "occ_hr": "Stara godina", "occ_en": "New Year's Eve"}];
